INSERT INTO `accreditation_instrument` VALUES (1,'',1,'Skrining dilakukan pada kontak pertama didalam atau di luar rumah sakit.	  ','','','',10,1,6,1,2012,NULL,NULL,NULL,NULL,NULL,NULL,'2013-08-02 07:00:00',1,'A'),(2,'',2,'Berdasarkan hasil skrining ditentukan apakah kebutuhan pasien sesuai dengan misi dan sumber daya rumah sakit. ( lihat juga TKP 3.2, EP.2 )	  ','','','',10,1,6,1,2012,NULL,NULL,NULL,NULL,NULL,NULL,'2013-08-02 07:00:00',1,'A'),(3,'',3,'Pasien hanya diterima apabila rumah sakit dapat menyediakan pelayanan yang dibutuhkan pasien rawat inap dan rawat jalan yang tepat.	  ','','','',10,1,6,1,2012,NULL,NULL,NULL,NULL,NULL,NULL,'2013-08-02 07:00:00',1,'A'),(4,'',4,'Ada suatu proses untuk melengkapi hasil tes diagnostik dan tanggung jawab untuk menetapkan apakah pasien diterima, dipindahkan/ transfer atau di rujuk.	  ','','','',10,1,6,1,2012,NULL,NULL,NULL,NULL,NULL,NULL,'2013-08-02 07:00:00',1,'A'),(5,'',5,'Ada kebijakan yang menetapkan bahwa skrining dan tes diagnosa yang mana merupakan standar sebelum penerimaan pasien.	  ','','','',10,1,6,1,2012,NULL,NULL,NULL,NULL,NULL,NULL,'2013-08-02 07:00:00',1,'A'),(6,'',6,'Pasien tidak dirawat, dipindahkan atau dirujuk sebelum diperoleh hasil tes yang dibutuhkan tersedia.	  ','','','',10,1,6,1,2012,NULL,NULL,NULL,NULL,NULL,NULL,'2013-08-02 07:00:00',1,'A'),(7,'',1,'Proses pendaftaran pasien rawat jalan distandardisir. 	  ','','','',10,2,6,1,2012,NULL,NULL,NULL,NULL,NULL,NULL,'2013-08-02 07:00:00',1,'A'),(8,'',2,'Proses admisi pasien rawat inap distandardisir. (lihat juga TKP.6.1, EP.3)	  ','','','',10,2,6,1,2012,NULL,NULL,NULL,NULL,NULL,NULL,'2013-08-02 07:00:00',1,'A'),(9,'',3,'Ada proses  penerimaan pasien emergensi ke unit rawat inap	  ','','','',10,2,6,1,2012,NULL,NULL,NULL,NULL,NULL,NULL,'2013-08-02 07:00:00',1,'A'),(10,'',4,'Ada proses untuk menahan pasien untuk observasi.   	  ','','','',10,2,6,1,2012,NULL,NULL,NULL,NULL,NULL,NULL,'2013-08-02 07:00:00',1,'A'),(11,'',5,'Ada proses penanganan pasien bila tida