INSERT INTO `accreditation_instrument_class` VALUES (1,'KELOMPOK STANDAR PELAYANAN BERFOKUS PADA PASIEN ',0,2012,'2013-08-18 09:33:23',1,'A'),(2,'KELOMPOK STANDAR MANAJEMEN RUMAH SAKIT',0,2012,'2013-08-18 09:33:24',1,'A'),(3,'SASARAN KESELAMATAN PASIEN',0,2012,'2013-08-18 09:33:25',1,'A'),(4,'SASARAN MILENIUM DEVELOPMENT GOALS ',0,2012,'2013-08-18 09:33:27',1,'A'),(5,'KELOMPOK STANDAR PELAYANAN BERFOKUS PADA PASIEN',0,2018,'2017-09-23 00:00:00',1,'A'),(6,'KELOMPOK STANDAR MANAJEMEN RUMAH SAKIT',0,2018,'2017-09-23 00:00:00',1,'A'),(7,'SASARAN KESELAMATAN PASIEN',0,2018,'2017-09-23 00:00:00',1,'A'),(8,'PROGRAM NASIONAL',0,2018,'2017-09-23 00:00:00',1,'A'),(9,'INTEGRASI PENDIDIKAN KESEHATAN DALAM PELAYANAN RUM',0,2018,'2017-09-23 00:00:00',1,'A');
