  `standard_focus` varchar(100) DEFAULT NULL,
  `standard_name` text NOT NULL,
  `standard_objective` text NOT NULL,
  `standard_maximum_score` int(11) NOT NULL DEFAULT 0,
  `standard_version` year(4) NOT NULL,
  `standard_post_date` datetime NOT NULL,
  `standard_user_id` int(11) NOT NULL,
  `standard_record_status` char(1) NOT NULL,
  PRIMARY KEY (`standard_id`)
) ENGINE=MyISAM AUTO_INCREMENT=1493 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci ROW_FORMAT=DYNAMIC;
