LOCK TABLES `hsi_module_item` WRITE;
/*!40000 ALTER TABLE `hsi_module_item` DISABLE KEYS */;
INSERT INTO `hsi_module_item` VALUES (1,'Kerusakan struktural utama sebelumnya atau kegagalan bangunan rumah sakit','Terdapat banyak kerusakan dan tidak ada perbaikan','Terdapat kerusakan dan hanya sebagian yang diperbaiki','Sedikit atau tidak ada kerusakan, atau bangunan sepenuhnya telah diperbaiki','JIKA PERISTIWA SEMACAM ITU TIDAK TERJADI DI SEKITAR RUMAH SAKIT, BIARKAN KOTAK TETAP KOSONG DAN BERIKAN KOMENTAR','A',6.25,'2022-06-08 06:51:56'),(2,'Rumah sakit dibangun dan/atau diperbaiki menggunakan standar keamanan saat ini','Standar keamanan saat ini tidak digunakan','Standar keamanan saat ini hanya sebagian saja yang diterapkan dalam pembangunan','Standar keamanan saat ini sepenuhnya diterapkan dalam pembangunan',NULL,'A',12.5,'2022-06-08 06:51:56'),(3,'Efek dari renovasi atau modifikasi pada tampilan struktur rumah sakit','Terdapat banyak renovasi atau modifikasi yang dilakukan yang juga memberikan pengaruh besar pada tampilan struktur rumah sakit','Renovasi yang cukup dan/atau modifikasi dengan sedikit efek pada tampilan struktur rumah sakit','Sedikit renovasi atau modifikasi; tidak ada modifikasi yang dilakukan; atau kebanyakan dari modifikasi berfungsi untuk memperkuat struktur atau tidak mempunyai efek negatif',NULL,'A',6.25,'2022-06-08 06:51:56'),(4,'Struktur Sistem Desain','Memiliki sistem yang buruk','Memiliki struktur sistem desain yang moderat','Memiliki struktur sistem desain yang baik',NULL,'A',7.5,'2022-06-08 06:51:56'),(5,'Kondisi Bangunan','Retak pada tanah dan lantai; Kerusakan sebagian besar disebabkan oleh cuaca atau lamanya pemakaian','Sebagian kerusakan hanya disebabkan oleh cuaca atau lama pemakaian','Tidak ada kerusakan atau retak',NULL,'A',7.5,'2022-06-08 06:51:56'),(6,'Kondisi bahan konstruksi','Karat dengan pengelupasan permukaannya; retak lebih besar dari 3mm (beton), deformasi yang berlebihan (besi dan kayu)','Retak antara 1 dan 3 mm (beton), deformasi (besi dan kayu) atau karat tanpa adanya pengelupasan','Retak kurang dari 1 mm (beton), tidak ada deformasi ataupun karat',NULL,'A',6,'2022-06-08 06:51:56'),(7,'Interaksi elemen nonstruktural dengan struktur','Partisi dinding kaku melekat pada struktur; plafon yang tergantung atau fasad yang berhubungan dengan struktur, kerusakan yang terjadi memiliki efek signifikan pada struktur','Beberapa elemen non struktural sebelumnya yang berinteraksi dengan struktur, kerusakan yang terjadi tidak mempengaruhi struktur','Tidak ada elemen non struktural yang mempengaruhi struktur',NULL,'A',4.5,'2022-06-08 06:51:56'),(8,'Kedekatan bangunan (untuk gempa deteksi getaran)','Terpisah kurang dari 0,5% dari tinggi gedung terpendek dua bangunan yang berdekatan','Terpisah antara 0,5% dan 1,5% dari tinggi gedung terpendek dua bangunan yang berdekatan','Terpisah lebih dari 1,5% dari tinggi gedung terpendek dua bangunan yang berdekatan',NULL,'E',2.25,'2022-06-08 06:51:56'),(9,'Kedekatan bangunan (efek terowongan angin dan api)','Terpisah kurang dari 5m','Terpisah antara 5m dan 15m','Terpisah lebih dari 15m',NULL,'A',2.25,'2022-06-08 06:51:56'),(10,'Redundansi struktural ','Kurang dari tiga baris perlawanan di setiap arah','Tiga baris di setiap arah atau baris tanpa orientasi ortogonal','Lebih dari tiga baris di setiap arah ortogonal',NULL,'A',4.5,'2022-06-08 06:51:56'),(11,'Rincian dari struktur, termasuk penghubung','Tidak ada bukti catatan bangunan yang direkayasa, atau dibangun sesuai dengan standar desain lama','Dibangun sesuai dengan standar desain sebelumnya dan tidak ada pekerjaan perkuatan ke standar saat ini','Dibangun sesuai dengan standar saat ini',NULL,'A',3,'2022-06-08 06:51:56'),(12,'Rasio kekuatan kolom terhadap kekuatan balok','Kekuatan balok jelas lebih besar dari kekuatan kolom','Kekuatan balok mirip dengan kekuatan kolom','Kekuatan kolom lebih besar dari kekuatan balok',NULL,'A',4.5,'2022-06-08 06:51:56'),(13,'Keamanan Fondasi','Tidak ada bukti bahwa fondasi dirancang sesuai dengan standar (ukuran pondasi, survei tanah) dan / atau ada bukti kerusakan; tidak ada rencana yang tersedia','Sedikit bukti (gambar, survei tanah) bahwa fondasi dirancang sesuai dengan standar; dan / atau ada bukti kerusakan sedang','Bukti kuat bahwa fondasi dirancang sesuai standar dengan bukti kuat tidak ada kerusakan',NULL,'A',6,'2022-06-08 06:51:56'),(14,'Penyimpangan dalam membangun rencana struktur (kekakuan, massa, resistensi)','Bentuknya tidak beraturan dan strukturnya tidak seragam','Bentuk pada rencana tidak teratur tetapi strukturnya seragam','Bentuk pada rencana teratur dan struktur memiliki rencana seragam, dan tidak ada elemen yang akan menyebabkan torsi yang signifikan',NULL,'A',3,'2022-06-08 06:51:56'),(15,'Penyimpangan di ketinggian bangunan','Unsur terputus-putus atau tidak beraturan yang signifikan, variasi ketinggian bangunan yang signifikan','Beberapa elemen terputus-putus atau tidak beraturan, beberapa variasi dalam ketinggian bangunan','Tidak ada elemen yang terputus-putus atau tidak beraturan, sedikit atau tidak ada variasi dalam ketinggian bangunan',NULL,'A',3,'2022-06-08 06:51:56'),(16,'Penyimpangan di ketinggian lantai','Ketinggian lantai berbeda lebih dari 20%','Memiliki ketinggian yang sama (berbeda kurang dari 20%, tetapi lebih dari 5%)','Lantai memiliki ketinggian yang sama (berbeda kurang dari 5%)',NULL,'A',3,'2022-06-08 06:51:56'),(17,'Integritas struktural atap','Atap monopitch atau atap datar, dan/atau atap besar','Atap beton prategang, atap fabel dengan landai yang saling terhubung, bukan atap yang besar','Ditekankan pada atap beton atau atap limasyang saling terhubung, bukan merupakan atap yang besar',NULL,'A',4.5,'2022-06-08 06:51:56'),(18,'Ketahanan struktural terhadap bahaya selain gempa bumi dan angin kencang','Ketahanan struktural yang rendah terhadap bahaya di area rumah sakit','Ketahanan struktural yang cukup (terkait dengan langkah pengurangan bahaya struktural)','Ketahanan struktural yang baik (terkait dengan langkah pengurangan bahaya)',NULL,'A (except EW)',13.5,'2022-06-08 06:51:56'),(19,'Kerusakan besar dan perbaikan dari unsur-unsur nonstruktural','Terjadi kerusakan besar dan tidak ada perbaikan yang dilakukan','Kerusakan yang moderat, tetapi bangunan hanya diperbaiki sebagian','Sedikit atau tidak ada kerusakan, atau bangunan sepenuhnya telah diperbaiki','JIKA PERISTIWA SEPERTI INI TIDAK TERJADI DI SEKITAR RUMAH SAKIT, BIARKAN KOTAK TETAP KOSONG DAN BERIKAN KOMENTAR','A',3,'2022-06-08 06:51:56'),(20,'Kondisi dan keamanan dari pintu, pintu keluar dan pintu masuk','Pintu, pintu keluar dan pintu masuk berada dalam kondisi buruk, mengalami kerusakan yang dapat mempengaruhi fungsinya ataupun elemen, sistem atau kinerjalainnya; lebar pintu masuk kurang dari 115cm','Dalam kondisi yang stabil, terjadi kerusakan tetapi tidak mempengaruhi elemen, sistem atau kinerja lainnya; atau lebar pintu masuk kurang dari 115 cm','Berada dalam kondisi bagus, tidak ada atau sedikit potensi atas kerusakan yang mempengaruhi fungsinya sendiri atau elemen, sistem atau operator lainnya; dan = lebar pintu masuk sama dengan atau lebih besar dari 115 cm',NULL,'A',2,'2022-06-08 06:51:56'),(21,'Kondisi dan keamanan jendela dan shutter','Berada dalam kondisi yang buruk, terdapat kerusakan yang mempengaruhi fungsinya dan elemen, sistem atau kinerja lainnya (misalnya pelindung kaca yang lemah/tidak kuat)','Berada dalam kondisi stabil, terdapat kerusakan yang tidak mempengaruhi fungsinya dan elemen, sistem, kinerja lainnya','Berada dalam kondisi yang bagus, tidak ada atau sedikit potensi akan kerusakan yang dapat mempengaruhi fungsinya sendiri ataupun elemen, sistem, kinerja lainnya; kaca pelindung (misalnya kaca polikarbonat, kaca film) telah ditambahkan dalam kategori kriti',NULL,'A',1,'2022-06-08 06:51:56'),(22,'Kondisi dan keamanan unsur-unsur lain dari building envelope (misalnya dinding luar, facing)','Building envelope (dinding selubung bangunan) berada dalam kondisi yang buruk, terdapat kerusakan yang mempengaruhi fungsinya ataupun elemen, sistem, kinerja lainnya','Berada dalam kondisi stabil, terjadi kerusakan yang tidak mempengaruhi fungsinya ataupun elemen, sistem, kinerja lainnya','Berada dalam kondisi yang  bagus, tidak ada atau sedikit potensi kerusakan yang mempengaruhi fungsinya ataupun elemen, sistem, kinerja lainnya',NULL,'A',1,'2022-06-08 06:51:56'),(23,'Kondisi dan keamanan atap','Berada dalam kondisi yang buruk dengan kerusakan yang mempengaruhi fungsinya ataupun elemen, sistem, kinerja lainnya','Berada dalam kondisi stabil, terjadi kerusakan yang tidak mempengaruhi fungsinya ataupun elemen, sistem, kinerja lainnya','Berada dalam kondisi yang bagus, tidak ada atau sedikit potensi kerusakan yang mempengaruhi fungsinya ataupun elemen, sistem, kinerja lainnya',NULL,'A',2,'2022-06-08 06:51:56'),(24,'Kondisi dan keamanan pagar dan parapets','Berada dalam kondisi yang buruk dengan kerusakan yang mempengaruhi  fungsinya ataupun elemen, sistem, kinerja lainnya','Terdapat kerusakan yang tidak mempengaruhi fungsinya ataupun elemen, sistem, kinerja lainnya','Tidak ada atau sedikit potensi kerusakan yang mempengaruhi fungsinya ataupun elemen, sistem, kinerja lainnya',NULL,'A',1,'2022-06-08 06:51:56'),(25,'Kondisi dan Keamanan dinding perimeter dan pagar','Dinding perimeter dan pagar berada dalam kondisi yang buruk dengan kerusakan yang mempengaruhi fungsinya ataupun elemen, sistem, kinerja lainnya','Berada dalam kondisi stabil, terdapat kerusakan yang tidak mempengaruhi fungsinya ataupun elemen, sistem, kinerja lainnya','Berada dalam kondisi yang bagus, tidak ada atau sedikit potensi kerusakan yang mempengaruhi fungsinya ataupun elemen, sistem, kinerja lainnya',NULL,'A',1,'2022-06-08 06:51:56'),(26,'Kondisi dan keamanan dari unsur arsitektur lain (misalnya cornice, ornamen, cerobong asap, tanda)','Elemen arsitektur lain berada dalam kondisi yang buruk dengan kerusakan yang mempengaruhi fungsinya ataupun elemen, sistem, kinerja lainnya','Berada dalam kondisi stabil, terdapat kerusakan yang tidak mempengaruhi fungsinya ataupun elemen, sistem, kinerja lainnya','Berada dalam kondisi yang bagus, tidak ada atau sedikit potensi kerusakan yang mempengaruhi fungsinya ataupun elemen, sistem, kinerja lainnya',NULL,'A',1,'2022-06-08 06:51:56'),(27,'Kondisi yang aman untuk pergerakan di luar gedung rumah sakit','Hambatan atau kerusakan terhadap struktur atau jalan dan trotoar akan mempengaruhi akses masuk kendaraan dan pejalan kaki ke bangunan atau membahayakan pejalan kaki','Hambatan atau kerusakan terhadap struktur jalan dan trotoar tidak mempengaruhi akses pejalan kaki, tetapi mempengaruhi akses kendaraan','Tidak ada hambatan, sedikit atau tidak ada potensi yang dapat mempengaruhi akses pejalan kaki atau kendaraan',NULL,'A',1,'2022-06-08 06:51:56'),(28,'Kondisi yang aman untuk pergerakan di dalam gedung (misalnya koridor, tangga)','Hambatan atau kerusakan terhadap elemen dapat mempengaruhi  pergerakan di dalam gedung dan membahayakan orang didalamnya','Hambatan atau kerusakan terhadap elemen tidak mempengaruhi pergerakan di dalam gedung, tetapi mempengaruhi pergerakan peralatan stretcher','Tidak ada hambatan, sedikit atau tidak ada potensi yang dapat mempengaruhi pergerakan orang atau peralatan stretcher',NULL,'A',2,'2022-06-08 06:51:56'),(29,'Kondisi dan keamanan dinding dan partisiinternal','Dinding dan partisi internal berada dalam kondisi yang buruk dengan kerusakan yang mempengaruhi fungsinya ataupun elemen, sistem, kinerja lainnya','Berada dalam kondisi stabil, terdapat kerusakan yang tidak mempengaruhi fungsinya ataupun elemen, sistem, kinerja lainnya','Berada dalam kondisi yang bagus, tidak ada atau sedikit potensi kerusakan yang mempengaruhi fungsinya ataupun elemen, sistem, kinerja lainnya',NULL,'A',2,'2022-06-08 06:51:56'),(30,'Kondisi dan keamanan langit-langit palsu atau ditangguhkan','Langit-langit palsu atau ditangguhkan berada dalam kondisi yang buruk dengan kerusakan yang mempengaruhi fungsinya ataupun elemen, sistem, kinerja lainnya','Berada dalam kondisi stabil, terdapat kerusakan yang tidak mempengaruhi fungsinya ataupun elemen, sistem, kinerja lainnya','Berada dalam kondisi yang bagus, tidak ada atau sedikit potensi kerusakan yang mempengaruhi fungsinya ataupun elemen, sistem, kinerja lainnya','JIKA RUMAH SAKIT TIDAK MEMPUNYAI LANGIT-LANGIT PALSU ATAU DITANGGUHKAN, BIARKAN KOTAK TETAP KOSONG DAN BERIKAN KOMENTAR.','A',2,'2022-06-08 06:51:56'),(31,'Kondisi dan keamanan sistem lift','Sistem lift dalam kondisi buruk, mengalami kerusakan yang mempengaruhi fungsi darinya dan elemen, sistem atau operasi yang lain','berada dalam kondisi normal, mengalami kerusakan tetapi tidak mempengaruhi fungsi darinya dan elemen, sistem atau operasi yang lain','berada dalam kondisi yang bagus, tidak ada atau sedikit potensi kerusakan yang mempengaruhi fungsi darinya dan elemen, sistem atau operasi yang lain','JIKA TIDAK ADA LIFT, BIARKAN KOTAK TETAP KOSONG DAN BERIKAN KOMENTAR','A',1.2,'2022-06-08 06:51:56'),(32,'Kondisi dan keamanan tangga dan landai','kondisi yang buruk, terdapat kerusakan atau halangan, yang akan mempengaruhi fungsi daripadanya atau elemen, sistem atau kinerja yang lain','dalam kondisi normal, terdapat kerusakan tetapi kerusakan dan hambatan tersebut tidak mempengaruhi fungsinya sendiri dan elemen, sistem, atau kinerja lainnya','dalam kondisi yang baik, tidak ada hambatan, berpotensi untuk tidak terjadi atau sedikit kerusakan yang tidak mempengaruhi fungsinya sendiri dan elemen, sistem atau kinerja lainnya','JIKA TIDAK ADA TANGGA DAN LANDAI, BIARKAN KOTAK TETAP KOSONG DAN BERIKAN KOMENTAR','A',2,'2022-06-08 06:51:56'),(33,'Kondisi dan keamanan penutup lantai','penutup lantai dalam kondisi yang buruk, terdapat kerusakan atau halangan, yang akan mempengaruhi fungsi daripadanya atau elemen, sistem atau kinerja yang lain','dalam kondisi normal, terdapat kerusakan tetapi kerusakan dan hambatan tersebut tidak mempengaruhi fungsinya sendiri dan elemen, sistem, atau kinerja lainnya','dalam kondisi yang baik, tidak ada hambatan, berpotensi untuk tidak terjadi atau sedikit kerusakan yang tidak mempengaruhi fungsinya sendiri dan elemen, sistem atau kinerja lainnya',NULL,'A',0.8,'2022-06-08 06:51:56'),(34,'Lokasi pelayanankritisrumah sakit dan peralatan di rumah sakit sehubungan dengan bahaya setempat','Tidak ada tindakan perlindungan; terdapat kerusakan, kegagalan dan hambatan atas pelayanan kritis dan kinerja rumah sakit dalam keadaan darurat dan bencana','perlindungan parsial pada pelayanan kritis dari bahaya setempat; kerusakan atas gangguan pelayanan kritis dan kinerja rumah sakit dalam kondisi darurat dan bencana','Banyak tindakan perlindungan yang diambil untuk melindungi pelayanan kritis; kemungkinan besar bahwa pelayanan kritis dan rumah sakit akan beroperasi tanpa atau sedikit gangguan dalam kondisi darurat dan bencana',NULL,'A',2.5,'2022-06-08 06:51:56'),(35,'Jalur akses rumah sakit','Jalur akses sesuai dengan hambatan dan kerusakan yang mempengaruhi akses dan fungsi dari elemen, sistem dan kinerja yang lain','Jalur akses sesuai dengan beberapa hambatan dan kerusakan yang tidak mempengaruhi akses dan fungsi','Tidak ada atau sedikit potensi atas hambatan atau kerusakan yang mempengaruhi akses dan fungsi dari elemen, sistem atau operasi lainnya',NULL,'A',2.5,'2022-06-08 06:51:56'),(36,'Pintu darurat dan jalur evakuasi','Jalur pintu keluar dan evakuasi tidak jelas ditandai dan banyak jalur yang ditutup','Beberapa jalur pintu darurat dan jalur evakuasi diberi petunjuk yang jelas dan bebas dari hambatan','Semua jalur dan pintu darurat atau evakuasi diberi petunjuk yang jelas dan bebas dari hambatan',NULL,'A',2.5,'2022-06-08 06:51:56'),(37,'Keamanan fisik bangunan, peralatan, staf dan pasien','Tidak ada','Terdapat beberapa perlindungan keamanan fisik (misalnya: temapt penyimpanan yang terkunci untuk menyimpan pasokan dan peralatan, aset dan kontrol persediaan)','Terdapat banyak perlindungan keamanan (misalnya: desain dan layout, batas fisik, kontrol akses dan sistem pintu keamanan, tempat penyimpanan peralatan yang terkunci)',NULL,'A',2.5,'2022-06-08 06:51:56'),(38,'Kapasitas alternatif sumber listrik (misalnya generator)','Tidak ada atau habisnya alternatif sumber listrik atau mencakup kurang dari 30% dari kebutuhan di area kritis, atau hanya dapat dimulai secara manual','Sumber alternatif mencakup 31 – 70% dari kebutuhan di area kritis dan dimulai secara otomatis dalam waktu kurang dari 10 detik','Sumber dimulai secara otomatis dalam waktu kurang dari 10 detik dan mencakup lebih dari 70% kebutuhan di area kritis',NULL,'A',2,'2022-06-08 06:51:56'),(39,'Tes reguler alternatif sumber listrik di area kritis','Diuji dengan beban penuh setiap 3 bulan atau lebih','Diuji dengan beban penuh setiap 1 sampai 3 bulan','Diuji dengan beban penuh minimal setiap bulan',NULL,'A',1,'2022-06-08 06:51:56'),(40,'Kondisi dan keamanan alternatif sumber listrik','Tidak ada alternatif sumber listrik; generator dalam kondisi buruk, tidak terlindungi','Generator dalam kondisi normal, terdapat sebagian perlindungan dan keamanan','Generator dalam kondisi bagus, aman dan bekerja dengan benar sesuai prosedur dalam keadaan darurat',NULL,'A',1.5,'2022-06-08 06:51:56'),(41,'Kondisi dan keamanan peralatan listrik, kabel dan saluran kabel','Peralatan listrik, kabel dan saluran kabel dalam kondisi buruk, tidak terlindungi','Peralatan listrik, kabel dan saluran kabel dalam kondisi normal; beberapa terlindungi sebagian','Peralatan listrik, kabel, dan saluran kabel dalam kondisi bagus, terjaga dan bekerja sesuai dengan kinerjanya',NULL,'A',0.8,'2022-06-08 06:51:56'),(42,'Sistem yang berlebihan untuk pasokan listrik lokal','Hanya terdapat satu jalur masuk untuk pasokan listrik lokal','Terdapat dua jalur masuk untuk pasokan listrik lokal','Terdapat lebih dari dua jalur masuk untuk pasokan listrik lokal',NULL,'A',0.8,'2022-06-08 06:51:56'),(43,'Kondisi dan keamanan control panel, overload breaker switch dan kabel','control panel atau elemen lain berada dalam kondisi yang buruk, tanpa perlindungan','Control panel atau elemen lainnya berada dalam kondisi normal; terdapat beberapa perlindungan parsial','Control panel atau elemen lain berada dalam kondisi bagus, terlindungi dan bekerja sesuai dengan kinerjanya',NULL,'A',0.5,'2022-06-08 06:51:56'),(44,'Sistem pencahayaan untuk daerah-daerah kritis di rumah sakit','Pencahayaan yang kurang, tidak ada tindakan perlindungan','Pencahayaan yang cukup di area kritis; terdapat perlindungan parsial','Pencahayaan yang baik dan cukup dengan tindakan perlindungan yang ada',NULL,'A',1,'2022-06-08 06:51:56'),(45,'Kondisi dan keamanan sistem pencahayaan internal dan eksternal','Sistem pencahayaan internal dan eksternal dalam kondisi yang buruk, tanpa perlindungan','Berada dalam kondisi stabil;  dengan beberapa tindakan perlindungan parsial','Berada dalam kondisi yang bagus, terlindungi dan bekerja sesuai dengan kinerjanya',NULL,'A',0.8,'2022-06-08 06:51:56'),(46,'Sistem listrik eksternal yang dipasang untuk penggunaan rumah sakit','Tidak ada substansi listrik yang dipasang untuk memenuhi kebutuhan rumah sakit','Substansi dipasang dengan beberapa tindakan perlindungan parsial, tetapi rentan akan kerusakan atau gangguan, tidak tersedia listrik yang cukup untuk memenuhi kebutuhan rumah sakit','Substansi listrik dipasang, terlindungi, dan terdapat listrik yang cukup untuk rumah sakit dalam kondisi darurat atau bencana',NULL,'A',0.8,'2022-06-08 06:51:56'),(47,'Pemeliharaan darurat dan pemulihan pasokan listrik dan sumber alternatif','Tidak ada dokumen prosedur dan catatan pemeliharaan/inspeksi','Terdapat dokumen prosedur, catatan pemeliharaan/inspeksi telah diperbarui, personil telah dilatih, tetapi sumber daya tidak tersedia','Terdapat dokumen prosedur, catatan pemeliharaan/inspeksi telah diperbarui, personil telah dilatih, dan sumber daya tersedia untuk implementasi pemeliharaan dan pemulihan dalam keadaan darurat',NULL,'A',0.8,'2022-06-08 06:51:56'),(48,'Kondisi dan keamanan antena','Antena dan bracing berada dalam kondisi yang buruk tanpa ada perlindungan','Antena dan bracing berada dalam kondisi stabil dengan beberapa tindakan perlindungan sebagian','Antena dan bracing berada dalam kondisi bagus, terjaga dan terlindungi','JIKA TIDAK ADA ANTENA, BIARKAN KOTAK TETAP KOSONG DAN BERIKAN KOMENTAR','A',0.4,'2022-06-08 06:51:56'),(49,'Kondisi dan keamanan sistem yang bertegangan rendah dan ekstra-rendah (internet dan telepon)','Sistem bertegangan rendah berada dalam kondisi yang buruk tanpa adanya perlindungan','Sistem bertegangan rendah berada dalam kondisi yang stabil dengan beberapa tindakan perlindungan sebagian','Kondisi yang bagus, terjaga dan terlindungi',NULL,'A',0.6,'2022-06-08 06:51:56'),(50,'Sistem komunikasi alternatif','Tidak terdapat alternatif sistem komunikasi, dan berada dalam kondisi yang  buruk atau tidak berfungsi','Alternatif sistem komunikasi di seluruh rumah sakit berada dalam kondisi yang stabil, tetapi tidak diuji secara berkala','Alternatif sistem komunikasi berada dalam kondisi yang bagus dan diuji secara berkala setidaknya setahun sekali',NULL,'A',1.25,'2022-06-08 06:51:56'),(51,'Kondisi dan keamanan peralatan dan kabel telekomunikasi ','Peralatan dan kabel telekomunikasi berada dalam kondisi yang buruk tanpa adanya perlindungan','Peralatan dan kabel berada dalam kondisi yang stabil dengan beberapa tindakan perlindungan parsial','Berada dalam kondisi yang bagus, terlindungi dan jauh dari bahaya',NULL,'A',0.25,'2022-06-08 06:51:56'),(52,'Efek dari sistem telekomunikasi eksternal pada komunikasi rumah sakit','Sistem telekomunikasi eksternal menyebabkan gangguan utama terhadap komunikasi rumah sakit','Sistem telkomunikasi eksternal menyebabkan gangguan moderat terhadap komunikasi rumah sakit','Komunikasi eksternal tidak menyebabkan gangguan terhadap komunikasi rumah sakit',NULL,'A',0.25,'2022-06-08 06:51:56'),(53,'Keamanan situs untuk sistem telekomunikasi','Situs untuk sistem telekomunikasi berada dalam kondisi yang buruk, memiliki risiko kegagalan yang tinggi akibat gangguan/hambatan; tidak terdapat perlindungan','Berada dalam kondisi stabil, dengan beberapa tindakan perlindungan parsial','Berada dalam kondisi yang bagus, terjaga dan terlindungi',NULL,'A',0.5,'2022-06-08 06:51:56'),(54,'Kondisi dan keamanan sistem komunikasi internal','Tidak terdapat sistem komunikasi internal atau berada dalam kondisi yang buruk','Sistem komunikasi internal berada dalam kondisi yang stabil, tetapi tidak terdapat sistem alternatif','Sistem komunikasi internal dan sistem cadangan bekerja sesuai dengan kinerjanya',NULL,'A',1.5,'2022-06-08 06:51:56'),(55,'Pemeliharaan pada kondisi darurat dan pemulihan standar dan alternatif sistem komunikasi','Tidak terdapat dokumen prosedur dan catatan pemeliharaan/inspeksi','Terdapat dokumen prosedur, data  pemeliharaan/inspeksi telah diperbarui, personil telah dilatih, tetapi sumber daya tidak tersedia','Terdapat dokumen prosedur, data pemeliharaan/inspeksi telah diperbarui, personil telah dilatih, dan sumber daya tersedia untuk implementasi pemeliharaan dan pemulihan keadaan darurat',NULL,'A',0.25,'2022-06-08 06:51:56'),(56,'Cadangan air untuk layanan dan fungsi rumah sakit','Cukup untuk 24 jam atau kurang dari 24 jam, atau tidak terdapat tangki air','Cukup untuk lebih dari 24 jam, tetapi kurang dari 72 jam','Cukup untuk minimal 72 jam',NULL,'A',3.5,'2022-06-08 06:51:56'),(57,'Lokasi tangki penyimpanan air','Tempatnya rentan dengan risiko tinggi atas gangguan/hambatan (misalnya struktur, arsitektur dan/atau sistem yang rentan atas bahaya)','Tempat terbuka atas risiko moderat (misalnya: kerentanan struktur, arsitektur dan/atau sistem)','Tempat tidak terbuka bagi umum sehingga jarang teridentifikasi adanya bahasa (misalnya: kerentanan struktur, arsitektur dan/atau sistem)','JIKA RUMAH SAKIT TIDAK MEMILIKI TANGKI PENYIMPANAN AIR, KOSONGKAN KOTAK BERIKUT DAN BERIKAN KOMENTAR','A',1,'2022-06-08 06:51:56'),(58,'Keamanan sistem distribusi air','kurang dari 60% berada dalam kondisi bagus untuk beroperasional seperti adanya','Antara 60% dan 80% berada dalam kondisi bagus','Diatas 80% berada dalam kondisi yang bagus',NULL,'A',1.2,'2022-06-08 06:51:56'),(59,'Alternatif pasokan air ke pasokan air biasa','Menyediakan kurang dari 30% dari kebutuhan sehari-hari dalam keadaan emergency dan scenario bencana','Menyediakan 30 – 80% untuk kebutuhan harian dalam keadaan darurat atau bencana','Menyediakan lebih dari 80% untuk kebutuhan harian dalam keadaan darurat atau bencana',NULL,'A',3,'2022-06-08 06:51:56'),(60,'Tambahan sistem pompa','Tidak ada cadangan pipa dan kapasitas operasional tidak memenuhi minimum kebutuhan harian','Pompa cadangan berada dalam kondisi stabil tetapi tidak dapat memenuhi kebutuhan minimum harian tamu','Semua cadangan pipa dan sistem cadangan beroperasional dan akan memenuhi kebutuhan minimum kebutuhan masyarakat atas air. sistem cadangan',NULL,'A',0.8,'2022-06-08 06:51:56'),(61,'Pemeliharaan darurat dan pemulihan sistem pasokan air','Tidak terdapat dokumen prosedur dan catatan pemeliharaan/inspeksi','Terdapat dokumen prosedur, dan catatan pemeliharaan/inspeksi yang telah diperbarui, personil telah dilatih, tetapi sumber daya tidak tersedial','Terdapat dokumen prosedur, catatan pemeliharaan/inspeksi yang telah diperbarui, personil telah dilatih, dan sumber daya tersedia untuk pelaksanaan pemeliharaan dan pemulihan keadaan darurat yang tersedia',NULL,'A',0.5,'2022-06-08 06:51:56'),(62,'Kondisi dan keamanan dari sistem perlindungan (pasif) kebakaran','Elemen yang rusak mempengaruhi fungsi dari element itu sendiri atau elemen lainnya, ataupun sistem maupun pelaksanaannya','Elemen yang rusak tidak mempengaruhi fungsi dari kinerja elemen lainnya','Tidak ada atau sedikit kemungkinan atas kerusakan yang dapat mempengaruhi fungsi dari element, sistem atau kinerjanya',NULL,'A',2.25,'2022-06-08 06:51:56'),(63,'Sistem deteksi api/asap','Tidak ada sistem yang dipasang','Sistem dipasang sebagian, tetapi tidak diperiksa dan diuji secara berkala','Sistem terpasang dan dijaga serta diuji secara berkala',NULL,'A',1.875,'2022-06-08 06:51:56'),(64,'Sistem pemadaman api (otomatis dan manual)','Tidak ada sistem yang dipasang; inspeksi tidak terjadi','Sistem dipasang sebagian, atau sistem dipasang seluruhnya tetapi tidak dijaga atau diuji; inspeksi tidak lengkap atau tidak diperbarui','Sistem dipasang seluruhnya dan secara berkala dijaga dan diuji; inspeksi lengkap dan terbaru',NULL,'A',1.875,'2022-06-08 06:51:56'),(65,'Pasokan air untuk pemadaman apI','Tidak terdapat sumber air tetap yang dapat digunakan untuk pemadaman api','Terdapat sumber air tetap yang dapat digunakan, tetapi jumlah air yang tersedia terbatas, dan tidak ada pemeliharaan and pengujian yang dilakukan','Terdapat sumber air tetap yang dapat digunakan untuk pemadaman api dengan signifikan jumlah air yang tersedia, serta secara berkala dipelihara dan diuji',NULL,'A',1.125,'2022-06-08 06:51:56'),(66,'Pemeliharaan kondisi darurat dan pemulihan sistem proteksi kebakaran','Tidak terdapat prosedur yang didokumentasikan dan catatan pemeliharaan/inspeksi tidak ada','Terdapat prosedur, catatan pemeliharaan/inspeksi telah diperbarui, personil telah dilatih, tetapi sumber daya tidak tersedia','Dokumen prosedur tersedia, catatan pemeliharaan/inspeksi telah diperbarui, personil telah dilatih, dan sumber daya untuk pelaksanaan pemeliharaan dan pemulihan pada kondisi darurat tersedia',NULL,'A',0.375,'2022-06-08 06:51:56'),(67,'Keamanan dari sistem air limbah yang tidak berbahaya','Tidak terdapat sistem pembuangan air limbah yang tidak berbahaya atau dalam kondisi yang buruk','Sistem dalam kondisi stabil, tetapi sedikit atau tidak ada tanda pemeliharaan','Sistem pembuangan air limbah bekerja dalam kondisi yang bagus dengan kapasitas dan pemeliharaan yang terjaga',NULL,'A',0.375,'2022-06-08 06:51:56'),(68,'Keamanan dari sistem pembuangan air limbah yang berbahaya','Tidak terdapat sistem untuk pembuangan air limbah yang berbahaya atau dalam kondisi yang buruk','Sistem dalam kondisi stabil, tetapi sedikit atau tidak ada tanda pemeliharaan','Sistem pembuangan air limbah bekerja dengan baik dengan kapasitas dan pemeliharaan yang baik',NULL,'A',1,'2022-06-08 06:51:56'),(69,'Keamanan dari sistem limbah padat yang tidak berbahaya','Tidak terdapat sistem pembuangan limbah padat yang tidak berbahaya atau dalam kondisi yang buruk','Sistem dalam kondisi stabil, tetapi sedikit atau tidak ada tanda pemeliharaan','Sistem pembuangan limbah padat bekerja dalam kondisi yang bagus dengan kapasitas dan pemeliharaan yang terjaga',NULL,'A',0.375,'2022-06-08 06:51:56'),(70,'Keamanan dari sistem limbah padat yang berbahaya','Tidak terdapat sistem pembuangan limbah padat yang berbahaya atau dalam kondisi yang buruk','Sistem dalam kondisi  stabil, tetapi sedikit atau tidak ada tanda pemeliharaan','Sistem pembuangan limbah padat bekerja dalam kondisi yang bagus dengan kapasitas dan pemeliharaan yang terjaga',NULL,'A',0.5,'2022-06-08 06:51:56'),(71,'Pemeliharaan darurat dan pemulihan dari semua jenis sistem manajemen limbah rumah sakit','Tidak terdapat prosedur dan catatan pemeliharaan/inspeksi','Terdapat dokumen prosedur, catatan pemeliharaan/inspeksi telah diperbarui, personil telah dilatih, tetapi sumber daya tidak tersedia','Terdapat dokumen prosedur, catatan pemeliharaan/inspeksi telah diperbarui, personil telah dilatih, dan sumber daya tersedia untuk pelaksanaan pemeliharaan dan pemulihan kondisi darurat',NULL,'A',0.25,'2022-06-08 06:51:56'),(72,'Bahan bakar cadangan','Tersedia cukup untuk 24 jam atau kurang, atau tidak terdapat tanki bahan bakar','Tersedia cukup untuk lebih dari 24 jam tetapi kurang dari 72 jam','Tersedia cukup untuk minimal 72 jam',NULL,'A',1.5,'2022-06-08 06:51:56'),(73,'Kondisi dan keamanan tangki bahan bakar di atas tanah dan/atau silinder','Tanki dalam kondisi yang buruk; tidak ada jangkar atau tangki kandang; tangki terletak di tempat yang tidak aman/berbahaya','Tangki dalam kondisi normal, jangkar dan bracing tidak mampu menahan bahaya utama; tangki kandang memiliki beberapa langkah atau sistem  keamanan dan perlindungan sendiri','Tangki dalam kondisi yang bagus; jangkar dan bracing dalam kondisi baik untuk menghalang bahaya; tangki kandang mempunyai sistem keamanan dan perlindungan yang kuat','JIKA RUMAH SAKIT TIDAK MEMILIKI LAYANAN LAYANAN BERIKUT, BIARKAN KOTAK TETAP KOSONG DAN BERIKAN KOMENTAR','A',1.5,'2022-06-08 06:51:56'),(74,'Lokasi aman untuk penyimpanan bahan bakar yang jauh dari bangunan rumah sakit','Tempat penyimpanan bahan bakar tidak dapat dijangkau dan tidak terletak di tempat yang aman','Terletak di lokasi yang bagus, bebas dari bahaya; terdapat beberapa langkah untuk perlindungan','Dalam kondisi dan lokasi yang bagus, aman serta langkah-langkah perlindungan yang lain; tangki bahan bakar dapat dijangkau','JIKA TIDAK ADA TANGKI BAHAN BAKAR, BIARKAN KOTAK TETAP KOSONG DAN BERIKAN KOMENTAR','A',1,'2022-06-08 06:51:56'),(75,'Kondisi dan keamanan sistem distribusi bahan bakar (katup, selang, penghubung)','Kurang dari 60% sistem tersebut beroperasi dalam kondisi aman','Antara 60% - 90% dari sistem dalam kondisi bagus dan mempunyai katup buka tutup otomatis','Lebih dari 90% sistem beroperasi dengan baik dan mempunyai katup bukat tutup otomatis','JIKA TIDAK ADA TANGKI DISTRIBUSI BAHAN BAKAR, BIARKAN KOTAK TETAP KOSONG DAN BERIKAN KOMENTAR','A',0.75,'2022-06-08 06:51:56'),(76,'Pemeliharaan kondisi darurat dan pemulihan cadangan bahan bakar','Tidak terdapat dokumen prosedur dan catatan pemeliharaan/inspeksi','Terdapat dokumen prosedur, catatan pemeliharaan/inspeksi telah diperbarui, personil telah dilatih, tetapi sumber daya tidak tersedia','Terdapat dokumen prosedur, catatan pemeliharaan/inspeksi telah diperbarui, personil telah dilatih, dan sumber daya tersedia untuk implementasi pemeliharaan dan pemulihan kondisi darurat',NULL,'A',0.25,'2022-06-08 06:51:56'),(77,'Lokasi tempat penyimpanan gas medis','Tidak terdapat tempat untuk gas medis, atau tempat untuk gas medis berada pada tingkat resiko kegagalan yang tinggi yang  disebabkan oleh gangguan/bahaya; tidak ada tindakan perlindungan, dan tempat penyimpanan tidak dapat diakses','Lokasi/area berada pada kondisi yang bagus; terdapat beberapa langkah untuk perlindungan parsial','Berada pada kondisi yang bagus, tempat yang aman dan langkah perlindungan lainnya; serta tempat penyimpanan terjangkau',NULL,'A',1,'2022-06-08 06:51:56'),(78,'Keamanan tempat penyimpanan untuk tangki gas dan/atau silinder','tangki gas medis dan silinder di tempat penyimpanan berada dalam kondisi yang buruk; tidak terdapat perlindungan, tidak terjamin keamanannya; personil tidak dilatih untuk mengoperasikan gas medis dan peralatan pemadam kebakaran','Tangki gas medis dan silinder dalam tempat penyimpanan berada dalam kondisi yang bagus, terdapat tindakan perlindungan parsial; kualitas dari jangkar dan bracing tidak memadai; personil telah dilatih untuk mengoperasikan peralatan','Kondisi bagus, aman dan terlindungi, jangkar dalam kondisi baik dengan kualitas bagus menghadapi masalah; gas medis dan peralatan pemadam kebakaran dioperasikan oleh personil yang terlatih',NULL,'A',1,'2022-06-08 06:51:56'),(79,'Kondisi dan keamanan sistem distribusi gas medis (misalnya katup, pipa, penghubung)','Kurang dari 60% sistem bekerja dengan kondisi bagus','Antara 60% dan 80% dari sistem bekerja dengan kondisi bagus','Lebih dari 80% dari sistem bekerja dengan kondisi bagus',NULL,'A',1,'2022-06-08 06:51:56'),(80,'Kondisi dan keamanan silinder gas medis dan peralatan terkait di rumah sakit','Tangki gas medis dan silinder yang terdapat di area rumah sakit berada dalam kondisi yang buruk, tidak terlindungi, terjamin keamanannya','tangki gas medis dan silinder berada dalam kondisi normal; kualitas jangkar dan brace tidak memadai, terdapat beberapa tindakan perlindungan parsial','Berada dalam kondisi yang bagus, aman dan terlindungi; jangkar memiliki kualitas bagus untuk hambatan utama',NULL,'A',1,'2022-06-08 06:51:56'),(81,'Ketersediaan sumber-sumber alternatif gas medis','sumber alternatif tidak tersedia','sumber alternatif tersedia tetapi pengiriman pasokan memerlukan lebih dari 15 hari','sumber alternatif yang cukup tersedia dalam jarak yang dekat (kurang dari 15 hari)',NULL,'A',0.75,'2022-06-08 06:51:56'),(82,'Pemeliharaan keadaan darurat dan pemulihan sistem gas medi','Tidak terdapat dokumen prosedur dan catatan pemeliharaan/inspeksi','Terdapat dokumen prosedur, catatan pemeliharaan/inspeksi yang terbaru; dan personil telah dilatih, tetapi sumber daya tidak tersedia','Terdapat dokumen prosedur, catatan pemeliharaan/inspeksi yang terbaru; dan personil telah dilatih dan sumber daya tersedia untuk implementasi pemeliharaan dan pemulihan kondisi darurat',NULL,'A',0.25,'2022-06-08 06:51:56'),(83,'Lokasi yang memadai untuk peralatan HVAC','Lingkungan sekitar HVAC tidak dapat dijangkau dan tidak terletak di tempat yang aman; tidak ada perlindungan','Lingkungan HVAC dapat dijangkau, terletak di tempat yang aman, dan terlindungi dari bahaya','Lingkungan sekitar HVAC dapat dijangkau, berada di tempat yang aman dan terlindungi dari bahaya',NULL,'A',0.75,'2022-06-08 06:51:56'),(84,'Keamanan lingkungan sekitar untuk peralatan HVAC ','Peralatan HVAC tidak dapat dijangkau, tidak dilindungi atau tidak aman dan terjaga','HVAC dapat dijangkau, terdapat perlindungan parsial','Peralatan HVAC dapat dijangkau, terdapat sejumlah perlindungan untuk peralatan tersebut',NULL,'A',1,'2022-06-08 06:51:56'),(85,'Keamanan dan kondisi operasi peralatan HVAC (misalnya boiler, knalpot)','Peralatan HVAC berada dalam kondisi yang buruk, tidak terjaga','Peralatan HVAC berada dalam kondisi normal; terlindungi, tetapi tidak dipelihara secara berkala','Berada dalam kondisi baik, aman dan terlindungi dari bahaya (misalnya: jangkar dengan kualitas bagus); dipelihara dan diuji secara berkala',NULL,'A',1,'2022-06-08 06:51:56'),(86,'Dukungan yang memadai untuk saluran dan review fleksibilitas dari saluran dan pipa yang melintasi ekspansi sendi','Kurangnya dukungan dan hubungan yang kaku','Dukungan yang stabil dengan hubungan yang fleksibel','Dukungan yang baik dengan hubungan yang fleksibel',NULL,'A',0.5,'2022-06-08 06:51:56'),(87,'Kondisi dan keamanan pipa, penghubung dan katup','kurang dari 60% pipa berada dalam kondisi bagus; perlindungan yang terbatas dari kerusakan','Antara 60% dan 80% berada dalam kondisi bagus; terdapat beberapa perlindungan parsial terhadap bahaya/kerusakan','Diatas 80% berada dalam kondisi bagus dan terjamin serta terlindungi dari bahaya/kerusakan',NULL,'A',0.5,'2022-06-08 06:51:56'),(88,'Kondisi dan keamanan peralatan AC ','unit AC berada dalam kondisi yang buruk, tidak terjaga','unit AC berada dalam kondisi normal dengan perlindungan parsial (misalnya: kualitas jangkar dan brace tidak memadai)','berada dalam kondisi yang bagus,  aman dan terlindungi dari bahaya (misalnya: jangkar dengan kualitas bagus)',NULL,'A',0.5,'2022-06-08 06:51:56'),(89,'Pengoperasian sistem AC (termasuk area tekanan negatif)','Sistem AC tidak mempunyai kapasitas untuk menciptakan zona bagi rumah sakit','Sistem AC membentuk zona, tetapi tidak memiliki kapasitas untuk memisahkan sirkulasi udara antara area berisiko tinggi dengan area lain di rumah sakit','Sistem AC dapat mengisolasi udara dari area berisiko tinggil; terdapat ruang tekanan negatif',NULL,'A',0.5,'2022-06-08 06:51:56'),(90,'Pemeliharaan kondisi darurat dan pemulihan sistem HVAC','Tidak terdapat dokumen prosedur dan catatan pemeliharaan/inspeksi','Terdapat dokumen prosedur, catatan pemeliharaan/inspeksi telah diperbarui, personil telah dilatih, tetapi sumber daya tidak tersedia','Terdapat dokumen prosedur, catatan pemeliharaan/inspeksi yang telah diperbarui, personil telah dilatih, dan sumber daya tersedia untuk implementasi pemeliharaan dan pemulihan kondisi darurat',NULL,'A',0.25,'2022-06-08 06:51:56'),(91,'Keamanan rak beserta Isinya','terletak di tempat yang tidak aman (atau di area seismik dan rawan angin, lebih dari 20% dari kasus tidak terpasang di dinding)','terletak di tempat yang aman (dan terpasang  di dinding, di area seismik dan rawan angina) dan 20-80% dari isi terjamin keamanannya','lebih dari 80% isi rak aman tersimpan dan terjamin isinya',NULL,'A',0.85,'2022-06-08 06:51:56'),(92,'Keamanan komputer dan printer','tidak ada perlindungan atas bahaya terhadap komputer','Komputer terletak di tempat yang aman, terlindungi sebagian dari bahaya','Komputer terletak di tempat yang aman, terjamin dengan perlindungan yang memadai',NULL,'A',0.85,'2022-06-08 06:51:56'),(93,'Keamanan peralatan medis dalam ruang operasi dan ruang pemulihan','Ruang operasi terletak di tempat yang tidak aman, peralatan tidak memadai atau dalam kondisi yang kurang atau tidak ada  perlindungan','Ruang operasi terdapat di tempat yang aman, peralatan cukup, dan terlindungi sebagian','Ruang operasi terletak di tempat yang aman, peralatan dalam kondisi bagus, terawat dan terlindungi',NULL,'A',0.765,'2022-06-08 06:51:56'),(94,'Kondisi dan keamanan peralatan radiologi dan imaging','Peralatan radiologi dan imaging terletak di tempat yang tidak aman, peralatan tidak memadai atau dalam kondisi yang kurang atau tidak ada perlindungan','Peralatan terdapat di tempat yang aman, cukup, dan terlindungi sebagian','Peralatan terletak di tempat yang aman, dalam kondisi bagus, terawat dan terlindungi',NULL,'A',0.765,'2022-06-08 06:51:56'),(95,'Kondisi dan keamanan peralatan dan persediaan laboratorium','Langkah-langkah biosafety kurang, peralatan laboratorium tidak memadai atau dalam kondisi yang buruk, atau tidak ada langkah-langkah perlindungan','Terdapat perlindungan, peralatan dalam kondisi yang memadai, dan beberapa langkah memberikan sebagian perlindungan','terdapat langkah-langkah biosafety, peralatan dalam kondisi yang bagus, terjamin dan memberikan perlindungan yang baik',NULL,'A',0.765,'2022-06-08 06:51:56'),(96,'Kondisi dan keamanan peralatan medis di unit layanan perawatan darurat','Peralatan medis tidak cukup atau dalam kondisi yang kurang atau tidak ada langkah-langkah perlindungan','Peralatan dalam kondisi yang bagus dan beberapa sudah  mendapatkanperlindungan','Peralatan dalam kondisi bagus, terjamin dan terdapat perlindungan',NULL,'A',0.765,'2022-06-08 06:51:56'),(97,'Kondisi dan keamanan peralatan medis di unit perawatan intensif atau menengah','Peralatan medis tidak cukup atau dalam kondisi yang kurang atau tidak ada langkah-langkah perlindungan','Peralatan dalam kondisi yang bagus dan beberapa sudah mendapatkan perlindungan','Peralatan dalam kondisi bagus, terjamin dan terdapat perlindungan',NULL,'A',0.765,'2022-06-08 06:51:56'),(98,'Kondisi dan keamanan peralatan dan perabotan di apotek','Peralatan di apotek tidak cukup atau dalam kondisi yang kurang atau tidak ada langkah-langkah perlindungan','Peralatan dalam kondisi yang bagus dan beberapa sudah  mendapatkan perlindungan','Peralatan dalam kondisi bagus, terjamin dan terdapat perlindungan',NULL,'A',0.765,'2022-06-08 06:51:56'),(99,'Kondisi dan keamanan peralatan dan perlengkapan dalam jasa sterilisasi','Peralatan tidak cukup atau dalam kondisi yang kurang atau tidak ada langkah-langkah perlindungan','Peralatan dalam kondisi yang bagus dan beberapa sudah mendapatkan perlindungan','Peralatan dalam kondisi bagus, terjamin dan terdapat perlindungan',NULL,'A',0.765,'2022-06-08 06:51:56'),(100,'Kondisi dan keamanan peralatan medis untuk keadaan darurat kebidanan dan perawatan bayi','Peralatan tidak cukup atau dalam kondisi yang kurang atau tidak ada langkah-langkah perlindungan','Peralatan dalam kondisi yang bagus dan beberapa sudah  mendapatkan perlindungan','Peralatan dalam kondisi bagus, terjamin dan terdapat perlindungan',NULL,'A',0.306,'2022-06-08 06:51:56'),(101,'Kondisi dan keamanan peralatan medis dan persediaan untuk perawatan darurat untuk luka bakar','Peralatan tidak cukup atau dalam kondisi yang kurang atau tidak ada langkah-langkah perlindungan','Peralatan dalam kondisi yang bagus dan beberapa sudah mendapatkan perlindungan','Peralatan dalam kondisi bagus, terjamin dan terdapat perlindungan',NULL,'A',0.306,'2022-06-08 06:51:56'),(102,'Kondisi dan keamanan medis peralatan kedokteran nuklir dan terapi radiasi','Peralatan tidak cukup atau dalam kondisi yang kurang atau tidak ada langkah-langkah perlindungan','Peralatan dalam kondisi yang bagus dan beberapa sudah mendapatkan perlindungan','Peralatan dalam kondisi bagus, terjamin dan terdapat perlindungan','JIKA RUMAH SAKIT BERIKUT TIDAK MEMILIKI LAYANAN SERVICE, BIARKAN KOTAK TETAP KOSONG DAN BERIKAN KOMENTAR','A',0.306,'2022-06-08 06:51:56'),(103,'Kondisi dan keamanan peralatan medis di layanan lain','Lebih dari 30% peralatan berisiko atas kegagalan bahan atau fungsional dan/atau peralatan menempatkan seluruh layanan operasi terhadap risiko langsung atau tidak langsung','10% - 30% dari peralatan berisiko atas kehilangan','lebih kecil dari 60% dari peralatan berisiko',NULL,'A',0.306,'2022-06-08 06:51:56'),(104,'Obat-obatan dan persediaan','tidak ada','persediaan kurang dari 72 jam sebagai kapasitas maksimum','testing',NULL,'A',1.836,'2022-06-08 06:51:56'),(105,'Disterilkan instrumen dan bahan lainnya','tidak ada','persediaan kurang dari 72 jam sebagai kapasitas maksimum','persediaan terjamin minimum 72 jam sesuai dengan kapasitas maksimum rumah sakit',NULL,'A',1.836,'2022-06-08 06:51:56'),(106,'Peralatan medis yang khusus digunakan dalam keadaan darurat dan bencana','tidak ada','persediaan kurang dari 72 jam sebagai kapasitas maksimum rumah sakit','persediaan terjamin minimum 72 jam sesuai dengan kapasitas maksimum rumah sakit',NULL,'A',1.53,'2022-06-08 06:51:56'),(107,'Pasokan gas medis','Kurang dari 10 hari','Antara 10 dan 15 hari','Antara 10 dan 15 hari',NULL,'A',1.836,'2022-06-08 06:51:56'),(108,'Mekanik volume ventilator','tidak ada','persediaan kurang dari 72 jam sebagai kapasitas maksimum rumah sakit','persediaan terjamin minimum 72 jam sesuai dengan kapasitas maksimum rumah sakit',NULL,'A',0.306,'2022-06-08 06:51:56'),(109,'Peralatan electromedical','tidak ada','persediaan kurang dari 72 jam sebagai kapasitas maksimum rumah sakit','persediaan terjamin minimum 72 jam sesuai dengan kapasitas maksimum rumah sakit',NULL,'A',0.306,'2022-06-08 06:51:56'),(110,'Peralatan dukungan hidup','tidak ada','persediaan kurang dari 72 jam sebagai kapasitas maksimum rumah sakit','persediaan terjamin minimum 72 jam sesuai dengan kapasitas maksimum rumah sakit',NULL,'A',0.765,'2022-06-08 06:51:56'),(111,'Persediaan, peralatan atau kecelakaan cart untuk berhentinya kardiopulmoner','tidak ada','persediaan dan peralatan untuk keadaan darurat seperti kardiopulmoner (atau kecelakaan cart) tersedia, tetapi kurang dari 72 jam sebagai kapasitas maksimum rumah sakit','persediaan dan peralatan untuk keadaan darurat kardiopulmoner (atau kecelakaan cart) terjamin minimum 72 jam sesuai dengan kapasitas maksimum rumah sakit',NULL,'A',0.306,'2022-06-08 06:51:56'),(112,'Komite keadaan darurat/bencana rumah sakit','tidak ada komite, atau hanya diwakili oleh 1-3 departemen','Komite terdiri dari 4-5 departemen, tetapi tidak berfungsi secara efektif','Komite terdiri dari 6 atau lebih departemen yang melaksanakan seluruh fungsinya',NULL,'A',3,'2022-06-08 06:51:56'),(113,'Tanggung jawab dan pelatihan anggota komite ','Komite tidak ada atau anggotanya tidak dilatih dan tanggung jawabnya tidak dijelaskan','Komite telah mendapatkan pelatihan dan telah diberikan tugas dan tanggung jawabnya masing-masing','Semua anggota telah dilatih dan benar telah menerima seluruh peran dan tanggung jawab yang harus mereka laksanakan',NULL,'A',1.05,'2022-06-08 06:51:56'),(114,'Koordinator manajemen yang ditunjuk untuk mengatur keadaan darurat dan bencana','Tidak ada staf yang ditunjuk untuk melaksanakan kewajibannya sebagai koordinator manajemen untuk mengatur keadaan darurat dan bencana','tugas coordinator manajemen untuk mengatur keadaan darurat dan  bencana telah ditugaskan kepada anggota staf, tetapi tugas ini bukanlah kerjaan utamanya','seorang anggota staf ditunjuk sebagai koordinator untuk mengatur keadaan darurat dan bencana sebagai tugas utamanya untuk dilaksanakan, dimana dia harus memenuhi semua perannya sesuai dengan program kesiapsiagaan rumah sakit',NULL,'A',1.2,'2022-06-08 06:51:56'),(115,'Program kesiapsiagaan untuk menguatkan respon dan pemulihan keadaan darurat dan bencana','program untuk memperkuat persiapan, respond dan pemulihan tidak ada atau, jika ada, tidak ada kegiatan yang telah dilakuakn','program tersebut ada dan beberapa aktifitas telah diimplementasikan','Program tersebut telah sepenuhnya dilaksanakan  sesuai dengan pimpinan Komite untuk keadaan darurat/bencana',NULL,'A',3.75,'2022-06-08 06:51:56'),(116,'Sistem manajemen insiden rumah sakit','tidak ada manajemen kejadian rumah sakit','Staf ditunjuk sebagai posisi manajemen keadaan darurat rumah sakit, tetapi tidak ada prosedur yang tertulis untuk pelaksanaan fungsinya','prosedur manajemen untuk rumah sakit ada dan seluruhnya dilaksanakan sesuai dengan aturan oleh seseorang yang telah dilatih sebagai koordinator',NULL,'A',1.2,'2022-06-08 06:51:56'),(117,'Pusat operasi darurat (EOC)','Tidak ada EOC atau berada di lokasi yang tidak aman','EOC yang ditunjuk berara di tempat yang aman, terjamin dan dapat ditemukan, tetapi mempunyai batas kapasitas  operasional dalam keadaan darurat','EOC berada di tempat yang aman, terjamin dan dapat dijangkau dengan banyak kapasitas operasional',NULL,'A',1.8,'2022-06-08 06:51:56'),(118,'Mekanisme koordinasi dan pengaturan kerjasama dengan lembaga manajemen darurat/bencana lokal','Tidak ada','pengaturan ada tetapi tidak sepenuhnya beroperasional','pengaturan ada dan sepenuhnya operasional',NULL,'A',1.5,'2022-06-08 06:51:56'),(119,'Mekanisme koordinasi dan pengaturan kerjasama dengan jaringan peduli kesehatan','Tidak ada','pengaturan ada tetapi tidak sepenuhnya beroperasional','pengaturan ada dan sepenuhnya operasional',NULL,'A',1.5,'2022-06-08 06:51:56'),(120,'Rencana respon rumah sakit untuk keaadaan darurat atau bencana','Rencana tidak terdokumentasi','rencana terdokumentasi, tapi tidak mudah diakses, tidak diperbarui (lebih dari 12 bulan sejak pendataan terakhir)','rencana ada, mudah diakses, ditinjau/diperbarui setidaknya setiap tahun, dan sumber daya tersedia untuk menjalankan rencana',NULL,'A',6.3,'2022-06-08 06:51:56'),(121,'Sub rencana khusus bahaya rumah sakit','sub rencana respon khusus bahaya tidak didokumentasikan','rencana terdokumentasikan dengan lengkap tapi tidak mudah diakses, tidak diperbarui(lebih dari 12 bulan  sejak tinjauan/pendataan terakhir)','dokumen rencana lengkap, ditinjau/diperbarui setidaknya setiap tahun, dan sumber daya tersedia untuk menjalankan rencana',NULL,'A',5.4,'2022-06-08 06:51:56'),(122,'Prosedur untuk mengaktifkan dan menonaktifkan rencana','prosedur tidak ada atau hanya sebagai dokumen','Terdapat prosedur, personil telah dilatih, tetapi prosedur tidak diperbarui atau diuji setiap tahunnya','prosedur yang terbaru dengan personil yang telah dilatih, dan telah diuji setidaknya setiap tahun',NULL,'A',1.26,'2022-06-08 06:51:56'),(123,'Pelaksanaan, evaluasi dan tindakan perbaikan atas rencana respon rumah sakit terhadap keadaan darurat dan bencana','rencana respon dan sub rencana belum diuji','rencana respon atau sub rencana diuji, tetapi tidak diuji setidaknya setiap tahun','rencana respon atau sub rencana diuji setidaknya setiap tahun dan diperbarui sesuai hasil yang ada',NULL,'A',3.6,'2022-06-08 06:51:56'),(124,'rencana respon atau sub rencana diuji setidaknya setiap tahun dan diperbarui sesuai hasil yang ada','rencana pemulihan tidak terdokumentasi','Rencana terdokumentasi lengkap, tetapi tidak mudah diakses, tidak diperbarui (lebih dari 12 bulan sejak tinjauan/pendataan terakhir)','Dokumen rencana lengkap, mudah diakses, dan meninjau/perbarui setidaknya setiap tahun',NULL,'A',1.44,'2022-06-08 06:51:56'),(125,'Komunikasi eksternal dan internal dalam keadaan darurat','sistem komunikasi internal dan eksternal pusat berfungsi tidak konsisten atau tidak sempurna; operator tidak terlatih dalam komunikasi darurat','sistem berfungsi sepenuhnya dan operator sepenuhnya terlatih dalam darurat, dan tes sistem dilakukan minimal setahun sekali','test',NULL,'A',2.8,'2022-06-08 06:51:56'),(126,'Direktori pemegang saham eksternal','tidak ada','direktori ada tapi datanya tidak diperbarui (lebih dari 3 bulan sejak pendataan terakhir)','direktori tersedia, sesuai data terbaru dan dipegang oleh staf respon darurat',NULL,'A',1.75,'2022-06-08 06:51:56'),(127,'Prosedur untuk komunikasi dengan publik dan media','Prosedur tidak ada, tidak ada juru bicara','Terdapat prosedur dan juru bicara yang telah dilatih','Terdapat prosedur, juru bicara yang telah dilatih, dan prosedur diuji setiap tahun',NULL,'A',1.4,'2022-06-08 06:51:56'),(128,'Manajemen informasi pasien','Prosedur untuk situasi darurat tidak ada','Terdapat prosedur untuk situasi darurat dengan personil yang telah dilatih tetapi tidak tersedia sumber daya','Terdapat prosedur untuk situasi darurat dengan personil yang telah dilatih, dan sumber daya tersedia untuk pelaksanaannya.',NULL,'A',1.05,'2022-06-08 06:51:56'),(129,'Daftar Kontak Staf','daftar kontak tidak ada','daftar ada, tetapi bukan data terbaru (lebih dari 3 bulan sejak pendataan terakhir)','daftar tersedia dan secara berkala diperbarui',NULL,'A',3,'2022-06-08 06:51:56'),(130,'Ketersediaan staf','kurang dari 50% staf tersedia untuk menjalankan tugas masing-masing departemen','50-80% dari staf tersedia','80-100% dari staf tersedia',NULL,'A',8,'2022-06-08 06:51:56'),(131,'Mobilisasi dan perekrutan personil selama keadaan darurat atau bencana','prosedur tidak ada atau hanya dalam bentuk dokumentasi','Terdapat prosedur dan personil telah dilatih, tetapi sumber daya manusia untuk keadaan darurat tidak tersedia','Terdapat prosedur, personil telah dilatih dan sumber daya manusia tersedia untuk memenuhi kebutuhan yang diperkirakan dalam keadaan darurat',NULL,'A',3,'2022-06-08 06:51:56'),(132,'Tugas-tugas yang diberikan kepada personil untuk respon dan pemulihan dalam keadaan darurat atau bencana','Tugas dalam keadaan darurat tidak ada atau tidak didokumentasikan','tugas diidentifikasikan, beberapa (tidak semua) personil menerima tugas tertulis atau pelatihan','tugas yang tertulis adalah yang ditetapkan, dan pelatihan atau latihan dilakukan untuk semua personil setidaknya setiap tahun',NULL,'A',5,'2022-06-08 06:51:56'),(133,'Kesejahteraan personil rumah sakit selama keadaan darurat atau bencana','tidak ada ruang dan langkah-langkah yang disediakan','tempat  telah disediakan, tetapi kurang dari 72 jam','Terjamin selama setidaknya 72 jam',NULL,'A',1,'2022-06-08 06:51:56'),(134,'Perjanjian dengan pemasok lokal dan vendor untuk keadaan darurat dan bencana','tidak ada pengaturan','Terdapat pengaturan, tetapi tidak sepenuhnya berjalan','pengaturan ada dan sepenuhnya dilaksanakan',NULL,'A',2,'2022-06-08 06:51:56'),(135,'Transportasi selama keadaan darurat','ambulan dan kendaraan lain sertatransportasi lainnya tidak tersedia','beberapa kendaraan tersedia, tetapi tidak dalam jumlah besar untuk keadaan darurat atau bencana','kendaraan yang tepat dalam jumlah yang cukup tersedia selama keadaan darurat dan bencana',NULL,'A',2,'2022-06-08 06:51:56'),(136,'Makanan dan minuman selama keadaan darurat','prosedur untuk makanan dan air minum untuk keadaan darurat tidak ada','prosedur ada, makanan dan air minum terjamin tetapi kurang untuk 72 jam','makanan dan air minum untuk keadaan darurat dijamin selama setidaknya 72 jam',NULL,'A',1.6,'2022-06-08 06:51:56'),(137,'Sumber daya keuangan selama keadaan darurat dan bencana','anggaran untuk keadaan darurat atau mekanisme untuk mengakses dana darurat tersebut tidak ada','dana dan mekanisme yang dianggarkan tersedia tetapi mencakup kurang dari 72 jam','dana terjamin cukup untuk selama 72 jam atau lebih',NULL,'A',2.4,'2022-06-08 06:51:56'),(138,'Kesinambungan layanan perawatan dalam keadaan darurat dan kritis','Prosedur tidak ada atau hanya sebagai dokumen','Terdapat prosedur, personil telah dilatih, tetapi tidak tersedia sepanjang waktu','Terdapat prosedur, personil telah dilatih dan sumber daya tersedia untuk menerapkan prosedur pada kapasitas maksimum rumah sakit dalam situasi darurat dan bencana sepanjang waktu',NULL,'A',5,'2022-06-08 06:51:56'),(139,'Kesinambungan layanan dukungan klinis yang penting','Prosedur tidak ada atau hanya sebagai dokumen','Terdapat prosedur, personil telah dilatih, tetapi tidak tersedia sepanjang waktu','Terdapat prosedur, personil telah  dilatih dan sumber daya tersedia untuk menerapkan prosedur pada kapasitas maksimum rumah sakit dalam situasi darurat dan bencana sepanjang waktu',NULL,'A',3.75,'2022-06-08 06:51:56'),(140,'Ekspansi ruang yang dapat digunakan untuk insiden korban masal','Ruang untuk ekspansi belum diidentifikasi','Ruang telah diidentifikasi; peralatan, perlengkapan, dan prosedur tersedia untuk dilakukan perluasan dan staf telah dilatih, tetapi pengujian tidak dilaksanakan','Terdapat prosedur dan telah diuji, personil telah dilatih dan peralatan, perlengkapan, serta sumber daya lainnya tersedia untuk melaksanakan perluasan ruang',NULL,'A',2.5,'2022-06-08 06:51:56'),(141,'Triase untuk keadaan darurat dan bencana','Tidak ada lokasi triase atau prosedur','Terdapat lokasi triase dan prosedur; personil telah dilatih, tetapi prosedur belum diuji untuk situasi darurat dan bencana','lokasi dan prosedur ada dan telah diuji, personil telah dilatih, serta sumber daya untuk pelaksanaannya sesuai pada kapasitas maksimum rumah sakit dalam situasi darurat dan bencana',NULL,'A',3,'2022-06-08 06:51:56'),(142,'Triase Tag dan perlengkapan logistik lain untuk insiden korban masal','Tidak ada','Pasokan mencakup kurang dari 72 jam dari kapasitas maksimum rumah sakit','Pasokan dijamin setidaknya selama 72 jam sesuai kapasitas maksimum rumah sakit',NULL,'A',0.75,'2022-06-08 06:51:56'),(143,'Sistem untuk arahan, transfer dan penerimaan pasien','Prosedur tidak ada atau ada hanya sebagai dokumen','Terdapat prosedur dan personil telah dilatih, tetapi prosedur belum diuji untuk situasi darurat atau bencana','Prosedur ada dan telah diuji, personil telah dilatih dan sumber daya tersedia untuk menerapkan langkahlangkah sesuai pada kapasitas maksimum rumah sakit dalam situasi darurat atau bencana',NULL,'A',2.5,'2022-06-08 06:51:56'),(144,'Infeksi pengawasan, pencegahan dan pengendalian prosedur.','kebijakan dan prosedur tidak ada; standar pencegahan untuk penanggulangan infeksi tidak dilakukan secara rutin','Terdapat kebijakan dan prosedur,standar tindakan pencegahan dilakukan secara rutin, personil telah dilatih, tetapi tingkat sumber daya yang diperlukan untuk situasi darurat dan bencana, termasuk epidemi, tidak tersedia','Terdapat kebijakan dan prosedur, langkah-langkah pencegahan dan pengendalian infeksi, personil telah dilatih, dan sumber daya tersedia untuk menerapkan langkahlangkah sesuai pada kapasitas maksimum rumah sakit dalam situasi darurat dan bencana',NULL,'A',3.75,'2022-06-08 06:51:56'),(145,'Layanan psikososial','Tidak adaprosedur atau ada hanya sebagai dokumen','Terdapat prosedur dan personil telah dilatih, tetapi jumlah sumber daya yang dibutuhkan untuk situasi darurat dan bencana tidak tersedia','Terdapat prosedur, personil telah dilatih, dan sumber daya tersedia untuk implementasi prosedur sesuai dengan  kapasitas maksimum rumah sakit pada situasi darurat dan bencana',NULL,'A',2.5,'2022-06-08 06:51:56'),(146,'Prosedur post-mortem bagi insiden kematian masal','Tidak adaprosedur atau ada hanya sebagai dokumen','Terdapat prosedur dan personil telah dilatih, tetapi jumlah sumber daya yang dibutuhkan untuk situasi darurat dan bencana tidak tersedia','Terdapat prosedur, personil telah dilatih, dan sumber daya tersedia untuk implementasi prosedur sesuai dengan kapasitas maksimum rumah sakit pada situasi darurat dan bencana',NULL,'A',1.25,'2022-06-08 06:51:56'),(147,'Rencana evakuasi','Tidak ada rencana atau ada hanya sebagai dokumen','Terdapat rencana dan personil telah dilatih sesuai prosedur, tetapi pengujian tidak dilakukan secara berkala','Terdapat rencana, personil telah dilatih, dan latihan pengungsian dilakukan setidaknya setiap tahun',NULL,'A',3.5,'2022-06-08 06:51:56'),(148,'Dekontaminasi untuk bahaya bahan kimia dan radiologis','Tidak ada peralatan pelindung yang dapat digunakan oleh staf rumah sakit, atau tidak ada area dokontaminasi','Terdapat peralatan pelindung yang dapat langsung digunakan oleh staf rumah sakit, serta terdapat area dokontaminasi, tetapi latihan staf tidak dilaksanakan secara berkala','Terdapat peralatan pelindung diri yang dapat digunakanm serta terdapat area  dokontaminasi dan personil telah dilatih dan diuji secara berkala',NULL,'BC',1.05,'2022-06-08 06:51:56'),(149,'Peralatan perlindungan diri dan isolasi untuk penyakit menular dan epidemi','Tidak terdapat peralatan pelindung diri untuk staf rumah sakit, atau tidak ada area isolasi','Pasokan tersedia untuk digunakan, tetapi hanya tersediakurang dari 72 jam sesuai kapasitas maksimum rumah sakit, terdapat area isolasi, tetapi pelatihan serta pengujian staf tidak dilaksanakan secara berkala','Pasokan tersedia minimal untuk 72 jam dari kapasitas maksimum rumah sakit dan terdapat sumber-sumber alternatif lain yang dapat digunakan, daerah isolasi didirikan, pelatihan dan pengujian staf sesuai dengan prosedur yang ada dilakukan minimal setahun sek',NULL,'B',0.35,'2022-06-08 06:51:56'),(150,'Prosedur keamanan dalam keadaan darurat','Tidak terdapat prosedur keamanan dalam keadaan darurat, atau hanya dalam bentuk dokumen','Terdapat prosedur dalam bentuk dokumen dan personil telah detraining sesuai prosedur keamanan dalam keadaan darurat, tetapi pengujian tidak dilakukan secara berkala','Personil telah dilatih dan pengujian prosedur dilaksanakan setidaknya setahun sekali',NULL,'A',1.75,'2022-06-08 06:51:56'),(151,'Keamanan jaringan sistem komputer ','Rumah sakit tidak mempunyai rencana dan prosedur keamanan sistem computer','Rumah sakit mempunyai keamanan cyber dasar tetapi tidak dimonitor dan diperbarui secara teartur','Rumah sakit  mempunyai sistem keamanan yang teratur dan terbaru yang diperbarui secara berkala',NULL,'A',0.35,'2022-06-08 06:51:56');
