DROP TABLE IF EXISTS `hsi_parameter`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `hsi_parameter` (
  `parameter_id` int(11) NOT NULL AUTO_INCREMENT,
  `parameter_tipe` int(11) NOT NULL COMMENT '0=root,1=cabang,2=ranting,3=sub ranting',
  `parameter_induk_id` int(11) NOT NULL,
  `parameter_root_id` int(11) NOT NULL,
  `parameter_trans` int(11) NOT NULL COMMENT '0=tidak,1=ya',
  `parameter_keterangan` text NOT NULL,
  `parameter_komentar` text NOT NULL,
  `parameter_bahaya` varchar(5) NOT NULL,
  `parameter_bobot` decimal(6,3) NOT NULL COMMENT 'bobot dalam %',
  `parameter_status` varchar(1) NOT NULL DEFAULT 'A' COMMENT 'A=AKTIF,D=DELETE',
  `parameter_komen` int(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`parameter_id`)
) ENGINE=InnoDB AUTO_INCREMENT=178 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
