CREATE TABLE `hsi_penilaian` (
  `penilaian_id` int(11) NOT NULL AUTO_INCREMENT,
  `penilaian_reff` varchar(50) NOT NULL COMMENT 'nomer referensi',
  `penilaian_kode_rs` varchar(10) NOT NULL COMMENT 'kode rumah sakit',
  `penilaian_periode` varchar(4) NOT NULL COMMENT 'tahun',
  `penilaian_parameter_id` int(11) NOT NULL COMMENT 'id tabel parameter_hsi',
  `penilaian_induk_id` int(11) NOT NULL,
  `penilaian_root_id` int(11) NOT NULL,
  `penilaian_rendah` int(11) NOT NULL COMMENT 'nilai rendah (1/0)',
  `penilaian_sedang` int(11) NOT NULL COMMENT 'nilai sedang (1/0)',
  `penilaian_tinggi` int(11) NOT NULL COMMENT 'nilai tinggi (1/0)',
  `penilaian_skor_rendah` decimal(7,3) NOT NULL COMMENT 'nilai rendah x bobot',
  `penilaian_skor_sedang` decimal(7,3) NOT NULL COMMENT 'nilai sedang x bobot',
  `penilaian_skor_tinggi` decimal(7,3) NOT NULL COMMENT 'nilai tinggi x bobot',
  `penilaian_skor_total` decimal(7,3) NOT NULL COMMENT 'total skor rendah+sedang+tinggi',
  `penilaian_uid` varchar(50) NOT NULL,
  `penilaian_input` datetime NOT NULL DEFAULT current_timestamp(),
  `penilaian_rekap_status` int(11) NOT NULL DEFAULT 0 COMMENT '1=sudah direkap,0=blm',
  `penilaian_record_status` varchar(1) NOT NULL DEFAULT 'A' COMMENT 'A=AKTIF,D=DELETE',
  `penilaian_komen` text NOT NULL,
  PRIMARY KEY (`penilaian_id`)
) ENGINE=InnoDB AUTO_INCREMENT=152 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
