DROP TABLE IF EXISTS `ikprssm_insiden`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ikprssm_insiden` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) DEFAULT NULL,
  `nip` varchar(50) DEFAULT NULL,
  `nama_petugas` varchar(100) DEFAULT NULL,
  `asal_pasien` tinyint(4) DEFAULT NULL,
  `tgl_masuk` date DEFAULT NULL,
  `jam_masuk` time DEFAULT NULL,
  `kd_pasien` varchar(20) DEFAULT NULL,
  `nama_pasien` varchar(100) DEFAULT NULL,
  `kelompok_umur` varchar(50) DEFAULT NULL,
  `nama_unit` varchar(100) DEFAULT NULL,
  `umur_tahun` int(11) DEFAULT NULL,
  `nama_kamar` varchar(100) DEFAULT NULL,
  `kelamin` varchar(20) DEFAULT NULL,
  `penjamin` varchar(50) DEFAULT NULL,
  `tgl_insiden` date DEFAULT NULL,
  `jam_insiden` time DEFAULT NULL,
  `insiden` text DEFAULT NULL,
  `kronologis_insiden` text DEFAULT NULL,
  `tempat_insiden` varchar(150) DEFAULT NULL,
  `jenis_insiden` varchar(20) DEFAULT NULL,
  `pelapor_insiden` varchar(50) DEFAULT NULL,
  `pelapor_lain_text` varchar(100) DEFAULT NULL,
  `insiden_pada` varchar(50) DEFAULT NULL,
  `insiden_pada_lain` varchar(100) DEFAULT NULL,
  `spesialisasi_pasien` varchar(50) DEFAULT NULL,
  `spesialisasi_lain` varchar(100) DEFAULT NULL,
  `akibat_insiden` varchar(100) DEFAULT NULL,
  `tindakan_segera` text DEFAULT NULL,
  `tindakan_oleh` varchar(50) DEFAULT NULL,
  `tindakan_tim` varchar(100) DEFAULT NULL,
  `tindakan_petugas_lain` varchar(100) DEFAULT NULL,
