han kalkulasi Biaya',NULL,0,NULL,0,'',NULL,NULL,NULL),(149,'IKARS',200,200,NULL,NULL,'Keterlambatan Asuhan Gizi Lanjutan ',NULL,NULL,NULL,2,'rate base','(Jumlah Keterlambatan Asuhan Gizi Lanjutan  pada bulan tersebut/Jumlah Pemberian Asuhan Gizi Lanjutan  pada bulan tersebut.) x 100%',1,'Keterlambatan Asuhan Gizi Lanjutan ',NULL,0,NULL,0,'',NULL,NULL,1),(150,'IKARS',201,201,NULL,NULL,'Kepatuhan Pemasangan Gelang Identitas pada Pasien IGD yang rawat inap',NULL,NULL,NULL,2,'rate base','(Jumlah Pasien IGD yang rawat inap  telah dilakukan pemasangan gelang/Jumlah Pasien IGD yang rawat inap) x 100%',1,'Kepatuhan Pemasangan Gelang Identitas pada Pasien IGD yang rawat inap',NULL,0,NULL,0,'',NULL,NULL,1),(151,'IKARS',202,202,NULL,NULL,'Ketepatan melakukan TBaK saat menerima instruksi verbal melalui telepon',NULL,NULL,NULL,2,'rate base','(Numerator Ketepatan melakukan TBaK saat menerima instruksi verbal melalui telepon/Denominator Ketepatan melakukan TBaK saat menerima instruksi verbal melalui telepon) x 100%',1,'Ketepatan melakukan TBaK saat menerima instruksi verbal melalui telepon',NULL,0,NULL,0,'',NULL,NULL,1),(152,'IKARS',203,203,NULL,NULL,'Kurangnya keamanan pengelolaan obat-obatab NORUM / LASA, elektrolit konsentrat, insulin, nutrisi parenteral, sedasi, heparin, agen radiokontras IV, dan agen kemoterapi. ',NULL,NULL,NULL,2,'rate base','(Numerator Kurangnya keamanan pengelolaan obat-obatab NORUM / LASA, elektrolit konsentrat, insulin, nutrisi parenteral, sedasi, heparin, agen radiokontras IV, dan agen kemoterapi. /Denominator Kurangnya keamanan pengelolaan obat-obatab NORUM / LASA, elekt',1,'Kurangnya keamanan pengelolaan obat-obatab NORUM / LASA, elektrolit konsentrat, insulin, nutrisi parenteral, sedasi, heparin, agen radiokontras IV, dan agen kemoterapi. ',NULL,0,NULL,0,'',NULL,NULL,1),(153,'IKARS',204,204,NULL,NULL,'Terjadinya pasien jatuh di lingkungan rumah sakit',NULL,NULL,NULL,2,'rate base','(Numerator Terjadinya pasien jatuh di lingkungan rumah sakit/Denominator Terjadinya pasien jatuh di lingkungan rumah sakit) x 100%',1,'Terjadinya pasien jatuh di lingkungan rumah sakit',NULL,0,NULL,0,'',NULL,NULL,1);
