--
-- Table structure for table `kalmut_katalogmutu_deskripsi`
--

DROP TABLE IF EXISTS `kalmut_katalogmutu_deskripsi`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `kalmut_katalogmutu_deskripsi` (
  `rowid` int(11) NOT NULL AUTO_INCREMENT,
  `idtopikmutu` double(5,0) NOT NULL,
  `indicator_id` int(11) DEFAULT NULL,
  `indicator_uuid` varchar(100) DEFAULT NULL,
  `ruanglingkup` varchar(120) DEFAULT NULL,
  `dimensimutu` varchar(120) DEFAULT NULL,
  `latarbelakang` varchar(200) DEFAULT NULL,
  `alasanpemilihan` varchar(200) DEFAULT NULL,
  `tipeindikator_s` char(1) DEFAULT NULL,
  `tipeindikator_p` char(1) DEFAULT NULL,
  `tipeindikator_h` char(1) DEFAULT NULL,
  `tujuan` varchar(200) DEFAULT NULL,
  `defop` text DEFAULT NULL,
  `metodepengumpulandata` varchar(200) DEFAULT NULL,
  `freqdatacollect` varchar(30) DEFAULT NULL,
  `periodeanalisis` varchar(30) DEFAULT NULL,
  `jumlahvarmutu` int(11) DEFAULT NULL,
  `nominator` text DEFAULT NULL,
  `denominator` text DEFAULT NULL,
  `jumlahvb` int(11) DEFAULT NULL,
  `formulatype` varchar(10) DEFAULT NULL,
  `formula` tinytext DEFAULT NULL,
  `satuan` varchar(30) DEFAULT NULL,
  `sumberdata` varchar(200) DEFAULT NULL,
  `standar` varchar(60) DEFAULT NULL,
  `target` varchar(60) DEFAULT NULL,
  `collectorpenanggungjawab` varchar(100) DEFAULT NULL,
  `mcmmutu` varchar(11) DEFAULT NULL,
  PRIMARY KEY (`rowid`,`idtopikmutu`)
) ENGINE=InnoDB AUTO_INCREMENT=160 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

