INSERT INTO `kalmut_katalogmutu_deskripsi` VALUES (1,1,1,'4e1789cc-6d29-11ec-a73f-1e544a7779f8','Ruang rawat inap ','Kelengkapan asesmen medis dalam waktu 24 jam setelah pasien masuk rawat inap','','','','P','','','Yang dimaksud asesmen medis lengkap dalam waktu 24 jam setelah pasien masuk rawat inap adalah :\n<ol>\n	<li>proses kegiatan mengevaluasi pasien</li>\n	<li>oleh tenaga medis</li>\n	<li>paling lambat 24 jam setelah pasien masuk rawat inap</li>\n	<li>meliputi mengumpulkan informasi, menganalisa informasi dan membuat rencana pelayanan untuk memenuhi semua kebutuhan pasien yang telah diidentifikasi</li>\n</ol>\n','',NULL,NULL,2,'Jumlah asesmen  lengkap yang dilakukan oleh tenaga medis dalam waktu 24 jam setelah pasien masuk  rawat inap dalam waktu 1 bulan','Jumlah total pasien yang masuk rawat inap dalam waktu 24 jam, dalam waktu 1 bulan',2,NULL,'(Jumlah asesmen  lengkap yang dilakukan oleh tenaga medis dalam waktu 24 jam setelah pasien masuk  rawat inap dalam waktu 1 bulan/Jumlah total pasien yang masuk rawat inap dalam waktu 24 jam, dalam waktu 1 bulan) x 100%','%','Rekam Medis','100','100','','IKARS'),(2,2,2,'4e178c92-6d29-11ec-a73f-1e544a7779f8','Instalasi rawat inap, Instalasi Pelayanan Intensif','Ketidakpatuhan pendokumentasian asesmen nyeri secara kontinyu di status pasien','','','','P','','','Terjadinya ketidakpatuhan perawat dalam pendokumentasian asesmen nyeri secara kontinyu di status pasien baik asesmen awal maupun ulang','',NULL,NULL,2,'Jumlah status pasien yang tidak ada dokumentasi  asesmen nyeri awal maupun ulang sesuai panduan manajemen nyeri per bulan','Jumlah seluruh  pasien dengan keluhan nyeri dalam bulan tersebut',2,NULL,'(Jumlah status pasien yang tidak ada dokumentasi  asesmen nyeri awal maupun ulang sesuai panduan manajemen nyeri per bulan/Jumlah seluruh  pasien dengan keluhan nyeri dalam bulan tersebut) x 100%','%','Rekam medis pasien',NULL,'5','','IKARS'),(3,3,3,'4e178d7e-6d29-11ec-a73f-1e544a7779f8','Instalasi laboratorium','Kerusakan sampel darah','','','I','','','','Terjadinya lisis atau pembekuan darah yang tidak sesuai dengan syarat sampel darah yang baik','',NULL,NULL,2,'Jumlah kerusakan sample darah per bulan','Jumlah sample darah pada bulan tersebut',2,NULL,'(Jumlah kerusakan sample darah per bulan/Jumlah sample darah pada bulan tersebut) x 100%','%','Catatan spesimen yang rusak',NULL,'0.5','','IKARS'),(4,4,4,'4e178fad-6d29-11ec-a73f-1e544a7779f8','Instalasi Laboratorium dan Instalasi Rawat Inap','Tidak terlaporkannya hasil kritis','','','I','','','','Keterlambatan melaporkan / tidak terlaporkannya hasil kritis, yaitu hasil laborat yang nilainya menurut patofisiologi penyakit berpotensi mengancam jiwa penderita sehingga membutuhkan penanganan medis secepat mungkin.','',NULL,NULL,2,'Jumlah jenis pemeriksaan dengan hasil kritis yang tidak terlaporkan per bulan','Jumlah jenis pemeriksaan dengan hasil kritis pada bulan tersebut',2,NULL,'(Jumlah jenis pemeriksaan dengan hasil kritis yang tidak terlaporkan per bulan/Jumlah jenis pemeriksaan dengan hasil kritis pada bulan tersebut) x 100%','%','Catatan pelaporan hasil kritis',NULL,'0','','IKARS'),(5,5,5,'4e179050-6d29-11ec-a73f-1e544a7779f8','Instalasi rawat jalan, Instalasi rawat inap, ICU, IGD','Penolakan expertise','','','','','','','Kejadian&nbsp; yang menunjukkan banyaknya penolakan expertise oleh dokter pengirim','',NULL,NULL,2,'Jumlah penolakan expertise per bulan','Jumlah seluruh pelayanan di radiologi pada bulan tersebut ',2,NULL,'(Jumlah penolakan expertise per bulan/Jumlah seluruh pelayanan di radiologi pada bulan tersebut ) x 100%','%','Laporan insiden ',NULL,'1','','IKARS'),(6,6,6,'4e1790e7-6d29-11ec-a73f-1e544a7779f8','Instalasi rawat jalan, IGD','Keterlambatan hasil foto rawat jalan','','','','','','','Angka yang menunjukkan  keterlambatan penerimaan hasil foto oleh pasien rawat jalan lebih dari tiga jam.jalan lebih dari tiga jam.','',NULL,NULL,2,'Jumlah pasien rawat jalan yang menerima hasil foto beserta bacaan lebih dari 3 jam per bulan','Jumlah seluruh pasien rawat jalan yang dilakukan tindakan foto rontgen pada bulan tersebut ',2,NULL,'(Jumlah pasien rawat jalan yang menerima hasil foto beserta bacaan lebih dari 3 jam per bulan/Jumlah seluruh pasien rawat jalan yang dilakukan tindakan foto rontgen pada bulan tersebut ) x 100%','%','Catatan pelayanan radiologi',NULL,'3','','IKARS'),(7,7,7,'4e17927f-6d29-11ec-a73f-1e544a7779f8','Instalasi radiologi','Pemeriksaan ulang radiologi','','','','P','','','Pemeriksaan ulang radiologiTerjadinya kesalahan pelaksanaan pemeriksaan radiologi','',NULL,NULL,2,'Jumlah pemeriksaan ulang radiologi per bulan ','Jumlah pasien yang dilakukan pemeriksaan radiologi pada bulan tersebut',2,NULL,'(Jumlah pemeriksaan ulang radiologi per bulan /Jumlah pasien yang dilakukan pemeriksaan radiologi pada bulan tersebut) x 100%','%','Laporan insiden',NULL,'0.5','','IKARS'),(8,8,8,'4e179316-6d29-11ec-a73f-1e544a7779f8','Instalasi radiologi','Tidak dilakukannya asesmen awal radiologi','','','I','','','','Asesmen awal radiologi adalah pemeriksaan pendahuluan yang dilakukan bagi semua pasien radiologi sebelum tindakan radiologi, serta didokumentasikan secara benar dan lengkap.','',NULL,NULL,2,'Jumlah tindakan radiologi yang tidak dilakukan asesmen awal radiologi per bulan','Jumlah seluruh tindakan radiologi dalam bulan tersebut',2,NULL,'(Jumlah tindakan radiologi yang tidak dilakukan asesmen awal radiologi per bulan/Jumlah seluruh tindakan radiologi dalam bulan tersebut) x 100%','%','Rekam medis (Form asesmen awal radiologi)',NULL,'1','','IKARS'),(9,9,9,'4e1793a7-6d29-11ec-a73f-1e544a7779f8','Instalasi kamar operasi','Tidak dilakukannya&nbsp; penandaan lokasi operasi','','','I','','','','Tidak dilakukannya penandaan lokasi operasi oleh operator','',NULL,NULL,2,'Jumlah kejadian tidak dilakukannya penandaan lokasi operasi pada semua kasus operasi yang harus dilakukan penandaan lokasi operasi per bulan.','Jumlah semua kasus operasi yang harus dilakukan penandaan lokasi operasi dalam bulan tersebut.',2,NULL,'(Jumlah kejadian tidak dilakukannya penandaan lokasi operasi pada semua kasus operasi yang harus dilakukan penandaan lokasi operasi per bulan./Jumlah semua kasus operasi yang harus dilakukan penandaan lokasi operasi dalam bulan tersebut.) x 100%','%','Status rekam medis pasien',NULL,'2','','IKARS'),(10,10,10,'4e17953d-6d29-11ec-a73f-1e544a7779f8','Instalasi  rawat inap','Operasi ulang dengan diagnosa sama dan atau komplikasinya<br />\n&nbsp;','','','','','','','Dilakukannya operasi ulang (operasi dengan prosedur yang sama) dengan kasus / diagnosa yang sama dengan operasi sebelumnya dan / atau karena komplikasinya, dalam waktu 7 hari atau kurang.','',NULL,NULL,2,'Jumlah operasi ulang dengan diagnosa sama / komplikasinya per bulan.','Jumlah seluruh operasi dalam bulan tersebut',2,NULL,'(Jumlah operasi ulang dengan diagnosa sama / komplikasinya per bulan./Jumlah seluruh operasi dalam bulan tersebut) x 100%','%','Status rekam medis pasien (laporan operasi)',NULL,'0','','IKARS'),(11,11,11,'4e1795cc-6d29-11ec-a73f-1e544a7779f8','Instalasi kamar operasi','Kesalahan Prosedur Operasi','','','','P','','','Terjadi insiden kesalahan prosedur operasi pada saat pasien dilakukan tindakan operasi','',NULL,NULL,2,'Jumlah insiden salah prosedur operasi pada pasien','Jumlah insiden salah prosedur operasi dalam bulan tersebut',2,NULL,'(Jumlah insiden salah prosedur operasi pada pasien/Jumlah insiden salah prosedur operasi dalam bulan tersebut) x 100%','%','Laporan insiden',NULL,'0','','IKARS'),(12,12,12,'4e17965c-6d29-11ec-a73f-1e544a7779f8','Instalasi Kamar  Operasi, Instalasi Rawat Inap','Kesalahan Lokasi Operasi','','','','P','','','Terjadinya insiden kesalahan lokasi pada saat pasien dilakukan tindakan operasi','',NULL,NULL,2,'Jumlah insiden kesalahan lokasi operasi pada pasien pembedahan','Jumlah insiden kesalahan lokasi operasi dalam bulan tersebut',2,NULL,'(Jumlah insiden kesalahan lokasi operasi pada pasien pembedahan/Jumlah insiden kesalahan lokasi operasi dalam bulan tersebut) x 100%','%','Laporan insiden',NULL,'0','','IKARS'),(13,13,13,'4e1797de-6d29-11ec-a73f-1e544a7779f8','Instalasi Kamar  Operasi, Instalasi Rawat Inap','Kesalahan Diagnosa Pre dan post operasi','','','','P','','','Terjadinya insiden kesalahan diagnosis pada pasien pra operasi, yang baru diketahui oleh operator pada saat durante operasi (diagnosis pra dan post operasi berbeda)','',NULL,NULL,2,'Insiden kesalahan diagnosis pra operasi','Insiden kesalahan diagnosis pra operasi dalam bulan tersebut',2,NULL,'(Insiden kesalahan diagnosis pra operasi/Insiden kesalahan diagnosis pra operasi dalam bulan tersebut) x 100%','%','Laporan insiden',NULL,'0','','IKARS'),(14,14,14,'4e17986c-6d29-11ec-a73f-1e544a7779f8','Instalasi Farmasi, Instalasi rawat inap, Instalasi rawat jalan, ICU, IGD, HD, Endoskopi','Kesalahan penyerahan perbekalan farmasi','','','','P','','','Kesalahan&nbsp; penyerahan&nbsp;&nbsp; perbekalan&nbsp;&nbsp; farmasi (obat, alat kesehatan, dan sebagainya) dari Instalasi Farmasi ke ruang perawatan','',NULL,NULL,2,'Jumlah kesalahan penyerahan perbekalan per bulan','Jumlah permintaan perbekalan dalam bentuk resep dan formulir permintaan pada bulan tersebut',2,NULL,'(Jumlah kesalahan penyerahan perbekalan per bulan/Jumlah permintaan perbekalan dalam bentuk resep dan formulir permintaan pada bulan tersebut) x 100%','%','Pelaporan insiden',NULL,'0','','IKARS'),(15,15,15,'4e1799f7-6d29-11ec-a73f-1e544a7779f8','Instalasi Farmasi, instalasi rawat inap, Instalasi rawat jalan, IGD, ICU, HD, Endoskopi','Ketidaktepatan pemberian obat (5 benar)','','','','P','','','Ketidaktepatan pemberian obat kepada pasien yang dinilai berdasarkan 5 benar, yaitu\n<ol>\n	<li>Benar pasien</li>\n	<li>Benar obat</li>\n	<li>Benar dosis</li>\n	<li>Benar waktu pemberian</li>\n	<li>Benar cara pemberian</li>\n</ol>\n','',NULL,NULL,2,'Jumlah kesalahan / ketidaktepatan pemberian obat  (5 Benar)','Jumlah total kesalahan/ketidaktepatan pemberian obat dalam bulan tersebut',2,NULL,'(Jumlah kesalahan / ketidaktepatan pemberian obat  (5 Benar)/Jumlah total kesalahan/ketidaktepatan pemberian obat dalam bulan tersebut) x 100%','%','Laporan insiden',NULL,'0','','IKARS'),(16,16,16,'4e179a87-6d29-11ec-a73f-1e544a7779f8','Instalasi kamar operasi','Ketidaklengkapan asesmen pre anestesi','','','I','','','','Ketidaklengkapan asesmen pre anestesi&nbsp; meliputi : dokter anestesi&nbsp; tidak visite pada saat pasien masih di ruang perawatan (pemeriksaan fisik, pemeriksaan penunjang, KIE / Informed Consent), dan rekam medis tidak terisi secara lengkap sebelum pasien dilakukan anestesi.','',NULL,NULL,2,'Jumlah pasien yang tidak dilakukan asesmen pre anestesi secara lengkap per bulan','Jumlah pasien operasi dengan anestesi dalam bulan tersebut',2,NULL,'(Jumlah pasien yang tidak dilakukan asesmen pre anestesi secara lengkap per bulan/Jumlah pasien operasi dengan anestesi dalam bulan tersebut) x 100%','%','Status rekam medis pasien',NULL,'1','','IKARS'),(17,17,17,'4e179c10-6d29-11ec-a73f-1e544a7779f8','Instalasi rawat inap','Kejadian Reaksi Transfusi','','','','P','','','Yang dimaksud kejadian reaksi transfusi adalah reaksi yang timbul akibat dilakukannya transfusi darah yang tidak sesuai dengan golongan darah pasien. (Reaksi incompatibilitas)','',NULL,NULL,2,'Jumlah kasus reaksi  transfusi darah per hari','Jumlah total kasus pemasangan transfusi darah (kantong darah) di hari tersebut',2,NULL,'(Jumlah kasus reaksi  transfusi darah per hari/Jumlah total kasus pemasangan transfusi darah (kantong darah) di hari tersebut) x 100%','%','Status rekam medis pasien, laporan insiden',NULL,'0','','IKARS'),(18,18,18,'4e179cf5-6d29-11ec-a73f-1e544a7779f8','Instalasi rekam medis','Ketidaklengkapan informed consent','','','I','','','','Informed Concent adalah persetujuan tindakan kedokteran yang diberikan oleh pasien/keluarga terdekatnya setelah mendapatkan penjelasan secara lengkap mengenai tindakan kedokteran yang akan dilakukan terhadap pasien tersebut serta risiko yang akan terjadi terhadap pasien.<br />\nKetidaklengkapan informed consent adalah tidak terisinya form informed consent secara lengkap, data maupun tanda tangan, baik pada lembar informasi maupun pada lembar consent.<br />\n&nbsp;','',NULL,NULL,2,'Informed consent yang tidak lengkap per bulan','Jumlah tindakan kedokteran dari seluruh pasien dalam bulan tersebut',2,NULL,'(Informed consent yang tidak lengkap per bulan/Jumlah tindakan kedokteran dari seluruh pasien dalam bulan tersebut) x 100%','%','Rekam medis pasien',NULL,'1','','IKARS'),(19,19,19,'4e179e81-6d29-11ec-a73f-1e544a7779f8','Instalasi rekam medis','Ketidaklengkapan catatan medis pasien (KLPCM)','','','','','','','Ketidaklengkapan pengisian catatan medis yang berisi seluruh informasi tentang pasien sesuai dengan formulir yang disediakan, khususnya resume medis dan resume keperawatan termasuk seluruh hasil pemeriksaan penunjang, dalam waktu 14 hari setelah pasien keluar dari Rumah Sakit','',NULL,NULL,2,'Jumlah catatan rekam medis yang belum lengkap dan benar dalam 14 hari per bulan','Jumlah catatan rekam medis dalam bulan tersebut',2,NULL,'(Jumlah catatan rekam medis yang belum lengkap dan benar dalam 14 hari per bulan/Jumlah catatan rekam medis dalam bulan tersebut) x 100%','%','Rekam medis pasien',NULL,'1','','IKARS'),(20,20,20,'4e179f15-6d29-11ec-a73f-1e544a7779f8','Intalasi rawat inap, ICU, Instalasi Rawat Jalan','Infeksi Daerah&nbsp; Operasi (IDO)','','','','P','','','Infeksi pasca operasi adalah adanya infeksi rumah sakit (HAIs) pada semua kategori luka sayatan operasi yang dilaksanakan di rumah sakit dan ditandai oleh rasa panas (kalor), nyeri (dolor), kemerahan (rubor), bengkak (tumor) gangguan fungsi (fungsiolesa) dan keluarnya nanah (pus) yang muncul dalam waktu lebih 3 x 24 jam sampai dengan 30 hari pasca operasi, atau sampai dengan 1 tahun jika terdapat implant','',NULL,NULL,2,'Jumlah pasien yang mengalami infeksi pasca operasi dalam satu bulan','Jumlah seluruh pasien yang dioperasi di rumah sakit dalam bulan tersebut',2,NULL,'(Jumlah pasien yang mengalami infeksi pasca operasi dalam satu bulan/Jumlah seluruh pasien yang dioperasi di rumah sakit dalam bulan tersebut) x 100%','%','Rekam medis pasien',NULL,'2','','IKARS'),(21,21,21,'4e17a09d-6d29-11ec-a73f-1e544a7779f8','Intalasi rawat inap, ICU','Sepsis','','','','P','','','Sepsis yang terjadi setelah pasien dirawat di rumah sakit','',NULL,NULL,2,'Jumlah pasien sepsis per bulan','Jumlah pasien rawat inap pada  bulan tersebut',2,NULL,'(Jumlah pasien sepsis per bulan/Jumlah pasien rawat inap pada  bulan tersebut) x 100%','%','Rekam medis pasien',NULL,'1','','IKARS'),(22,22,22,'4e17a135-6d29-11ec-a73f-1e544a7779f8','Intalasi rawat inap, ICU','Infeksi Luka Infus (ILI / Plebitis)','','','','P','','','Keadaan infeksi yang terjadi disekitar tusukan atau bekas tusukan jarum infus di pembuluh darah perifer dan timbul minimal 48 jam setelah pemasangan (sesuai pedoman surveilans infeksi Kemenkes RI tahun 2011).','',NULL,NULL,2,'Jumlah kasus infeksi luka infus per bulan','Jumlah hari pemasangan infus dalam bulan tersebut',2,NULL,'(Jumlah kasus infeksi luka infus per bulan/Jumlah hari pemasangan infus dalam bulan tersebut) x 1&permil;','&permil;','Rekam medis pasien',NULL,'20','','IKARS'),(23,23,23,'4e17a2fa-6d29-11ec-a73f-1e544a7779f8','Intalasi rawat inap, ICU','Infeksi Aliran Darah Primer&nbsp; (IADP)','','','','P','','','Keadaan infeksi yang terjadi akibat masuknya mikroba melalui peralatan yang dimasukkan langsung ke sistem pembuluh darah melalui insersi intravena kateter, baik berupa kateter vena maupun arteri dalam rangka perawatan maupun diagnostik (CVC / Central Venous Catheter, vena perifer / infus, double lumen untuk hemodialisa) infeksi timbul minimal 3 kali 24 jam&nbsp; (72 jam) setelah pemasangan.','',NULL,NULL,2,'Jumlah kasus infeksi aliran darah primer karena pemasangan intravaskular kateter  perbulan','Jumlah hari pemasangan intravaskular kateter dalam bulan tersebut',2,NULL,'(Jumlah kasus infeksi aliran darah primer karena pemasangan intravaskular kateter  perbulan/Jumlah hari pemasangan intravaskular kateter dalam bulan tersebut) x 1&permil;','&permil;','Rekam medis pasien',NULL,'10','','IKARS'),(24,24,24,'4e17a48e-6d29-11ec-a73f-1e544a7779f8','Intalasi rawat inap, Instalasi Pelayanan Intensif','Infeksi Saluran Kemih (ISK)','','','','P','','','Keadaan&nbsp; infeksi&nbsp; yang&nbsp; terjadi&nbsp; disekitar&nbsp; uretra atau selang kateter dan timbul setelah 3 kali 24 jam dilakukan pemasangan kateter di rumah sakit.','',NULL,NULL,2,'Jumlah kasus infeksi karena pemasangan kateter per bulan','Jumlah hari pemasangan kateter dalam bulan tersebut',2,NULL,'(Jumlah kasus infeksi karena pemasangan kateter per bulan/Jumlah hari pemasangan kateter dalam bulan tersebut) x 1&permil;','&permil;','Rekam medis pasien',NULL,'10','','IKARS'),(25,25,25,'4e17a61d-6d29-11ec-a73f-1e544a7779f8','Instalasi Pelayanan Intensif','Pneumonia akibat pemakaian ventilator (Ventilator Associated Pneumonia /VAP)','','','','P','','','Ventilator Associated Pneumonia (VAP) adalah pneumonia yang terjadi akibat pemasangan ventilator di rumah sakit.','',NULL,NULL,2,'Jumlah VAP  atau pneumonia yang terjadi akibat pemasangan ventilator per bulan','Jumlah hari pemakaian Endotracheal Tube (ETT) pada bulan tersebut',2,NULL,'(Jumlah VAP  atau pneumonia yang terjadi akibat pemasangan ventilator per bulan/Jumlah hari pemakaian Endotracheal Tube (ETT) pada bulan tersebut) x 1&permil;','&permil;','Rekam medis pasien',NULL,'20','','IKARS'),(26,26,26,'4e17a7ca-6d29-11ec-a73f-1e544a7779f8','Instalasi Rawat Inap dan Instalasi Pelayanan Intensif, Unit stroke','Kejadian dekubitus selama masa perawatan<br />\n&nbsp;','','','','P','','','Kerusakan/kematian kulit sampai jaringan dibawah kulit, bahkan menembus otot sampai mengenai tulang akibat adanya penekanan pada suatu area secaraterus menerus sehingga mengakibatkan gangguan sirkulasi darah setempat, yang timbul minimal 3 x 24 jam setelah rawat inap','',NULL,NULL,2,'Jumlah kasus luka dekubitus per bulan','Jumlah pasien tirah baring pada bulan tersebut',2,NULL,'(Jumlah kasus luka dekubitus per bulan/Jumlah pasien tirah baring pada bulan tersebut) x 100%','%','Rekam medis pasien',NULL,'0','','IKARS'),(27,27,27,'4e17a963-6d29-11ec-a73f-1e544a7779f8','Semua unit ','Ketidaktepatan identifikasi pasien','','','','P','','','Ketidaktepatan identifikasi adalah kesalahan penentuan identitas pasien sejak awal pasien masuk sampai dengan pasien keluar,terhadap semua pelayanan yang diterima oleh pasien','',NULL,NULL,2,'Jumlah insiden ketidaktepatan identifikasi pasien','Jumlah total insiden ketidaktepatan identifikasi pasien dalam bulan tersebut',2,NULL,'(Jumlah insiden ketidaktepatan identifikasi pasien/Jumlah total insiden ketidaktepatan identifikasi pasien dalam bulan tersebut) x 100%','%','Laporan insiden',NULL,'0','','IKARS'),(28,28,28,'4e17ab02-6d29-11ec-a73f-1e544a7779f8','Semua unit pelayanan','Insiden keamanan obat yang perlu diwaspadai','','','','P','','','Obat yang perlu diwaspadai (High allert ) adalah obat yang memiliki risiko lebih tinggi untuk menyebabkan&nbsp; / menimbulkan adanya komplikasi atau membahayakan pasien secara signifikan jika terdapat kesalahan penggunaan dan penyimpanan.','',NULL,NULL,2,'Insiden kejadian/kesalahan yang terkait dengan keamanan obat-obatan yang perlu diwaspadai','Jumlah total insiden/kejadian kesalahan yang terkait dengan keamanan obat-obatan yang perlu diwaspadai dalam bulan tersebut',2,NULL,'(Insiden kejadian/kesalahan yang terkait dengan keamanan obat-obatan yang perlu diwaspadai/Jumlah total insiden/kejadian kesalahan yang terkait dengan keamanan obat-obatan yang perlu diwaspadai dalam bulan tersebut) x 100%','%','Laporan insiden',NULL,'0','','IKARS'),(29,29,29,'4e17abab-6d29-11ec-a73f-1e544a7779f8','Seluruh area Rumah sakit ','Kejadian pasien jatuh','','','','P','','','Pasien jatuh di lingkungan rumah sakit oleh sebab apapun','',NULL,NULL,2,'Jumlah insiden pasien jatuh dalam bulan tersebut','Jumlah total insiden pasien jatuh dalam bulan tersebut',2,NULL,'(Jumlah insiden pasien jatuh dalam bulan tersebut/Jumlah total insiden pasien jatuh dalam bulan tersebut) x 100%','%','Laporan insiden',NULL,'0','','IKARS'),(30,30,30,'4e17ac44-6d29-11ec-a73f-1e544a7779f8','Unit Stroke, Instalasi Rawat Inap dan Instalasi Pelayanan Intensif','Pasien stroke ischemic yang tidak mendapatkan terapi anti trombotik pada saat KRS.','','','','P','','','<ul>\n	<li>Pemberian obat anti trombotik kepada pasien stroke ischemic</li>\n	<li>Preparat anti trombotik yang berisi: asam asetil salisilat, clopidogrel</li>\n	<li>Diisi oleh unit yang memulangkan pasien</li>\n</ul>\n','',NULL,NULL,2,'Jumlah pasien stroke ischemic yang tidak mendapatkan terapi anti trombotik pada saat KRS perbulan ','Jumlah seluruh pasien stroke ischemic yang KRS dalam bulan tersebut',2,NULL,'(Jumlah pasien stroke ischemic yang tidak mendapatkan terapi anti trombotik pada saat KRS perbulan /Jumlah seluruh pasien stroke ischemic yang KRS dalam bulan tersebut) x 100%','%','Rekam medis',NULL,'0','','IKARS'),(31,31,31,'4e17ae23-6d29-11ec-a73f-1e544a7779f8','Unit Stroke, Instalasi Rawat Inap dan Instalasi Pelayanan Intensif','Pasien stroke yang tidak mendapatkan edukasi selama masa perawatan di rumah sakit','','','','P','','','<ul>\n	<li>Edukasi pasien stroke adalah pemberian informasi dan pendidikan seputar stroke terhadap pasien dan / atau keluarga yang dilakukan oleh dokter penanggung jawab / perawat / fisioterapis / ahli gizi / apoteker atau tenaga kesehatan lainnya.</li>\n	<li>Diisi oleh unit yang pertama kali menerima&nbsp; pasien</li>\n</ul>\n','',NULL,NULL,2,'Jumlah pasien stroke yang tidak mendapatkan edukasi tentang stroke selama menjalani rawat inap selama satu bulan','Jumlah seluruh pasien stroke yang dirawat inap dalam bulan tersebut',2,NULL,'(Jumlah pasien stroke yang tidak mendapatkan edukasi tentang stroke selama menjalani rawat inap selama satu bulan/Jumlah seluruh pasien stroke yang dirawat inap dalam bulan tersebut) x 100%','%','Rekam medis',NULL,'0','','IKARS'),(32,32,32,'4e17aebe-6d29-11ec-a73f-1e544a7779f8','Instalasi Rawat Inap dan Instalasi Pelayanan Intensif','Pasien IMA yang tidak mendapatkan terapi aspirin (anti trombotik) dalam waktu 24 jam sejak datang ke Rumah Sakit.','','','','P','','','<ul>\n	<li>Pemberian terapi aspirin kepada pasien Infark Miokard Akut dalam waktu 24 jam sebelum atau sesudah tiba di rumah sakit .</li>\n	<li>Preparat anti trombotik yang berisi: asetil salisilat, clopidogrel</li>\n</ul>\n','',NULL,NULL,2,'Jumlah pasien IMA yang tidak  mendapatkan terapi aspirin/anti trombotik  dalam waktu 24 jam sejak datang ke RS per bulan ','Jumlah seluruh pasien IMA dalam bulan tersebut',2,NULL,'(Jumlah pasien IMA yang tidak  mendapatkan terapi aspirin/anti trombotik  dalam waktu 24 jam sejak datang ke RS per bulan /Jumlah seluruh pasien IMA dalam bulan tersebut) x 100%','%','Rekam medis',NULL,'0','','IKARS'),(33,33,33,'4e17af49-6d29-11ec-a73f-1e544a7779f8','Unit perinatologi','Bayi baru lahir yang tidak mendapatkan ASI Eksklusif selama rawat inap','','','','P','','','Pemberian Air Susu Ibu saja kepada bayi umur 0 &ndash; 6 bulan tanpa diberikan makanan atau minuman tambahan selain obat untuk terapi (pengobatan penyakit) selama masa rawat inap','',NULL,NULL,2,'Jumlah bayi baru lahir yang tidak mendapat ASI eksklusif selama masa rawat inap dalam satu bulan','Jumlah seluruh bayi baru lahir dalam bulan tersebut',2,NULL,'(Jumlah bayi baru lahir yang tidak mendapat ASI eksklusif selama masa rawat inap dalam satu bulan/Jumlah seluruh bayi baru lahir dalam bulan tersebut) x 100%','%','Rekam medis',NULL,'0','','IKARS'),(34,34,34,'4e17b0ef-6d29-11ec-a73f-1e544a7779f8','Instalasi Rawat Inap dan Instalasi Pelayanan Intensif','Pasien asma anak yang tidak menerima bronkodilator selama masa rawat inap','','','','P','','','Pemberian obat brokodilator pada pasien asma anak (&lt; 15 tahun) selama masa rawat inap','',NULL,NULL,2,'Jumlah pasien asma anak yang  tidak menerima bronkodilator selama masa rawat inap per bulan','Jumlah seluruh pasien asma anak dalam bulan tersebut',2,NULL,'(Jumlah pasien asma anak yang  tidak menerima bronkodilator selama masa rawat inap per bulan/Jumlah seluruh pasien asma anak dalam bulan tersebut) x 100%','%','Rekam medis',NULL,'0','','IKARS'),(35,35,35,'4e17b181-6d29-11ec-a73f-1e544a7779f8','Poli DOTS','Penanganan pasien tuberkulosis yang tidak sesuai strategi DOTS (Directly Observed Treatment Shortcourse)','','','','P','','','Pelayanan tuberkulosis dengan strategi DOTS adalah pelayanan tuberkulosis dengan 5 (lima) strategi penanggulangan tuberkulosis nasional.<br />\nPenegakan diagnosis dan follow up pengobatan pasien tuberkulosis harus melalui pemeriksaan mikroskopis tuberkulosis, pengobatan harus menggunakan paduan obat anti tuberkulosis yang sesuai dengan standar penanggulangan tuberkulosis nasional, dan semua pasien yang tuberkulosis yang diobati dievaluasi secara kohort sesuai dengan penanggulangan tuberkulosis nasional','',NULL,NULL,2,'Jumlah semua pasien tuberkulosis yang tidak ditangani sesuai dengan strategi DOTS per bulan','Jumlah seluruh pasien tuberculosis yang ditangani dalam bulan tersebut.',2,NULL,'(Jumlah semua pasien tuberkulosis yang tidak ditangani sesuai dengan strategi DOTS per bulan/Jumlah seluruh pasien tuberculosis yang ditangani dalam bulan tersebut.) x 100%','%','Rekam Medis',NULL,'0','','IKARS'),(36,36,36,'4e17b285-6d29-11ec-a73f-1e544a7779f8','Laboratorium, Poli DOTS','Proporsi pasien TB paru terkonfirmasi bakteriologis diantara terduga TB','','','I','P','','','Terduga TB : adalah semua pasien yang&nbsp; diduga menderita tuberkulosis<br />\nTerkonfirmasi bakteriologis : minimal 1 (satu) dari 3 (tiga) spesimen pemeriksaan dahak adalah BTA(+','',NULL,NULL,2,'Jumlah seluruh pasien terdiagnosa TB terkonfirmasi bakteriologis pada triwulan tersebut.','Jumlah seluruh pasien terduga TB yang melakukan pemeriksaan dahak mikroskopis pada bulan tersebut.',2,NULL,'(Jumlah seluruh pasien terdiagnosa TB terkonfirmasi bakteriologis pada triwulan tersebut./Jumlah seluruh pasien terduga TB yang melakukan pemeriksaan dahak mikroskopis pada bulan tersebut.) x 100%','%','TB 04, TB 06',NULL,'5-15','','IKARS'),(37,37,37,'4e17b448-6d29-11ec-a73f-1e544a7779f8','Poli DOTS','Angka konversi','','','','P','','','Angka konversi adalah prosentase pasien TB paru terkonfirmasi bakteriologis yang mengawali perubahan menjadi BTA negatif setelah menjalani masa pengobatan tahap awal&nbsp; diantara pasien TB paru terkonfirmasi bakteriologis yang diobati.','',NULL,NULL,2,'Jumlah seluruh pasien  TB paru terkonfirmasi bakteriologis dengan hasil pemeriksaan BTA akhir tahap awal negatif','Jumlah seluruh  pasien TB paru terkonfirmasi bakteriologis yang diobati.',2,NULL,'(Jumlah seluruh pasien  TB paru terkonfirmasi bakteriologis dengan hasil pemeriksaan BTA akhir tahap awal negatif/Jumlah seluruh  pasien TB paru terkonfirmasi bakteriologis yang diobati.) x 100%','%','TB 03, TB 04',NULL,'80','','IKARS'),(38,38,38,'4e17b4d4-6d29-11ec-a73f-1e544a7779f8','Poli DOTS','Angka kesembuhan','','','','P','','','Angka kesembuhan adalah angka yang menunjukkan prosentase pasien TB paru terkonfirmasi bakteriologis yang sembuh setelah selesai masa pengobatan diantara pasien TB paru terkonfirmasi bakteriologis&nbsp; yang tercatat.','',NULL,NULL,2,'Jumlah seluruh pasien TB paru terkonfirmasi bakteriologis yang sembuh.','Jumlah seluruh  pasien TB paru terkonfirmasi bakteriologis yang diobati',2,NULL,'(Jumlah seluruh pasien TB paru terkonfirmasi bakteriologis yang sembuh./Jumlah seluruh  pasien TB paru terkonfirmasi bakteriologis yang diobati) x 100%','%','TB 01 dan TB 03',NULL,'85','','IKARS'),(39,39,39,'4e17b55b-6d29-11ec-a73f-1e544a7779f8','Unit Kamar bersalin','Kematian ibu melahirkan karena eklampsi','','','','','','','Insiden yang menunjukkan banyaknya ibu yang meninggal karena eklampsia<br />\nEklampsia adalah suatu kelainan akut yang terjadi pada wanita hamil, bersalin, atau nifas yang ditandai dengan pre-eklampsia serta timbulnya kejang-kejang atau komplikasi lainnya, yang bukan disebabkan karena kelainan neurologi','',NULL,NULL,2,'Jumlah ibu meninggal karena eklampsia per bulan','Jumlah ibu dengan eklampsia pada bulan tersebut',2,NULL,'(Jumlah ibu meninggal karena eklampsia per bulan/Jumlah ibu dengan eklampsia pada bulan tersebut) x 100%','%','Rekam medis pasien',NULL,'0.5','','IKARS'),(40,40,40,'4e17b704-6d29-11ec-a73f-1e544a7779f8','Unit Kamar bersalin','Kematian ibu melahirkan karena perdarahan','','','','','','','Insiden yang menunjukkan banyaknya ibu yang meninggal karena perdarahan yang dapat terjadi pada semua kala dalam persalinan','',NULL,NULL,2,'Jumlah ibu melahirkan yang meninggal karena perdarahan perbulan','Jumlah ibu melahirkan dengan perdarahan pada bulan tersebut',2,NULL,'(Jumlah ibu melahirkan yang meninggal karena perdarahan perbulan/Jumlah ibu melahirkan dengan perdarahan pada bulan tersebut) x 100%','%','Rekam medis pasien',NULL,'0.5','','IKARS'),(41,41,41,'4e17b79c-6d29-11ec-a73f-1e544a7779f8','Unit Kamar bersalin','Ketidakmampuan menangani BBLR 1500-2500gr','','','','','','','BBLR adalah bayi yang lahir dengan berat badan 1500 &ndash; 2500 gr','',NULL,NULL,2,'Jumlah BBLR 1500 – 2500 gr dengan usia kehamilan &ge; 32 minggu  yang tidak berhasil ditangani  per bulan','Jumlah seluruh BBLR 1500 – 2500 gr dengan usia kehamilan &ge; 32 minggu yang ditangani dalam bulan tersebut',2,NULL,'(Jumlah BBLR 1500 – 2500 gr dengan usia kehamilan &ge; 32 minggu  yang tidak berhasil ditangani  per bulan/Jumlah seluruh BBLR 1500 – 2500 gr dengan usia kehamilan &ge; 32 minggu yang ditangani dalam bulan tersebut) x 100%','%','Rekam medis pasien',NULL,'0.5','','IKARS'),(42,42,42,'4e17b93b-6d29-11ec-a73f-1e544a7779f8','Unit Kamar Bersalin','Keterlambatan operasi sectio caesarea','','','','','','','Sectio caesarea adalah suatu tindakan pembedahan untuk mengeluarkan janin dari perut ibu.<br />\nKeterlambatan SC adalah penundaan pelaksanaan SC &gt; 30 menit dari waktu yang telah dijadwalkan','',NULL,NULL,2,'Jumlah ibu yang mengalami keterlambatan sectio caesarea pada bulan tersebut','Jumlah ibu yang mengalami sectio caesarea pada bulan tersebut',2,NULL,'(Jumlah ibu yang mengalami keterlambatan sectio caesarea pada bulan tersebut/Jumlah ibu yang mengalami sectio caesarea pada bulan tersebut) x 100%','%','Rekam medis pasien',NULL,'0.5','','IKARS'),(43,43,43,'4e17b9e6-6d29-11ec-a73f-1e544a7779f8','Unit Kamar Bersalin','Keterlambatan penyediaan darah','','','','','','','Adalah keterlambatan waktu menyediakan labu darah sesuai pesanan &gt; 60 menit terhitung mulai form permintaan darah diterima oleh petugas Bank darah rumah sakit sampai dengan labu darah diterima oleh perawat ruangan.','',NULL,NULL,2,'Jumlah ibu hamil / bersalin / nifas yang mengalami keterlambatan penyediaan darah pada bulan tersebut','Jumlah ibu hamil / bersalin / nifas yang membutuhkan transfusi darah pada bulan tersebut.',2,NULL,'(Jumlah ibu hamil / bersalin / nifas yang mengalami keterlambatan penyediaan darah pada bulan tersebut/Jumlah ibu hamil / bersalin / nifas yang membutuhkan transfusi darah pada bulan tersebut.) x 100%','%','Rekam medis pasien',NULL,'0.5','','IKARS'),(44,44,44,'4e17ba70-6d29-11ec-a73f-1e544a7779f8','Unit Kamar Bersalin','Kejadian tidak dilakukan Inisiasi Menyusu Dini (IMD) pada bayi baru lahir','','','','P','','','Inisiasi Menyusu Dini adalah bayi baru lahir diberi kesempatan untuk memulai atau inisiasi menyusu sendiri segera setelah lahir&nbsp; dengan membiarkan kontak kulit bayi dan ibu setidaknya satu jam atau sampai menyusu pertama selesai.','',NULL,NULL,2,'Jumlah bayi baru lahir yang tidak dilakukan IMD pada bulan tersebut','Jumlah seluruh bayi baru lahir yang dapat dilakukan IMD pada bulan tersebut',2,NULL,'(Jumlah bayi baru lahir yang tidak dilakukan IMD pada bulan tersebut/Jumlah seluruh bayi baru lahir yang dapat dilakukan IMD pada bulan tersebut) x 100%','%','Rekam medis pasien',NULL,'0.5','','IKARS'),(45,45