  PRIMARY KEY (`rowid`,`kodeunit`,`idtopikmutu`)
) ENGINE=InnoDB AUTO_INCREMENT=138 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
