--
-- Table structure for table `quality_indicator`
--

DROP TABLE IF EXISTS `quality_indicator`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `quality_indicator` (
  `indicator_id` int(11) NOT NULL AUTO_INCREMENT,
  `indicator_uuid` varchar(100) DEFAULT NULL,
  `indicator_name_id` int(11) DEFAULT NULL,
  `indicator_definition` text NOT NULL,
  `indicator_criteria_inclusive` text DEFAULT NULL,
  `indicator_criteria_exclusive` text DEFAULT NULL,
  `indicator_element` text NOT NULL,
  `indicator_source_of_data` varchar(100) NOT NULL,
  `indicator_type` varchar(50) NOT NULL,
  `indicator_value_standard` int(11) DEFAULT NULL,
  `indicator_monitoring_area` varchar(200) NOT NULL,
  `indicator_frequency` char(1) NOT NULL,
  `indicator_target` char(5) DEFAULT '0',
  `indicator_category_id` int(11) DEFAULT NULL COMMENT 'deprecated',
  `indicator_iscomplete` int(11) NOT NULL DEFAULT 0,
  `indicator_factors` varchar(5) NOT NULL COMMENT 'Faktor Pengali',
  `indicator_target_calculation` varchar(255) DEFAULT NULL,
  `indicator_units` varchar(10) NOT NULL COMMENT 'Satuan',
  `indicator_target_unit` varchar(255) DEFAULT NULL,
  `indicator_lcl` varchar(15) DEFAULT NULL,
  `indicator_ucl` varchar(15) DEFAULT NULL,
  `indicator_valid_date` date DEFAULT NULL,
  `indicator_last_updated` datetime DEFAULT NULL,
  `indicator_order_number` int(11) DEFAULT NULL,
  `indicator_record_status` char(1) NOT NULL DEFAULT 'A',
  `indicator_dasar_pemikiran` text DEFAULT NULL,
  `indicator_dimensi_mutu` varchar(50) DEFAULT NULL,
  `indicator_tujuan` text DEFAULT NULL,
  `indicator_periode_pengumpulan_data` text DEFAULT NULL,
  `indicator_instrumen_pengambilan_data` text DEFAULT NULL,
  `indicator_besar_sampel` text DEFAULT NULL,
  `indicator_cara_pengambilan_sampel` text DEFAULT NULL,
  `indicator_periode_analisis_pelaporan` text DEFAULT NULL,
  `indicator_penyajian_data` varchar(255) DEFAULT NULL,
  `indicator_penanggung_jawab` varchar(255) DEFAULT NULL,
  `indicator_insert_by` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`indicator_id`)
) ENGINE=InnoDB AUTO_INCREMENT=112 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

