LOCK TABLES `quality_indicator` WRITE;
/*!40000 ALTER TABLE `quality_indicator` DISABLE KEYS */;
INSERT INTO `quality_indicator` VALUES (1,'4e1789cc-6d29-11ec-a73f-1e544a7779f8',2,'Yang dimaksud asesmen medis lengkap dalam waktu 24 jam setelah pasien masuk rawat inap adalah :\n<ol>\n	<li>proses kegiatan mengevaluasi pasien</li>\n	<li>oleh tenaga medis</li>\n	<li>paling lambat 24 jam setelah pasien masuk rawat inap</li>\n	<li>meliputi mengumpulkan informasi, menganalisa informasi dan membuat rencana pelayanan untuk memenuhi semua kebutuhan pasien yang telah diidentifikasi</li>\n</ol>\n','','Pasien yang&nbsp; meninggal&nbsp; dalam waktu 24 jam setelah pasien masuk rawat inap atau pasien APS atau dirujuk sebelum waktu 24 jam','Kelengkapan asesmen medis dalam waktu 24 jam setelah pasien masuk rawat inap','Rekam Medis','Proses',100,'Ruang rawat inap ','M','100',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(2,'4e178c92-6d29-11ec-a73f-1e544a7779f8',2,'Terjadinya ketidakpatuhan perawat dalam pendokumentasian asesmen nyeri secara kontinyu di status pasien baik asesmen awal maupun ulang','Semua pasien dengan keluhan nyeri','','Ketidakpatuhan pendokumentasian asesmen nyeri secara kontinyu di status pasien','Rekam medis pasien','Proses dan outcome',NULL,'Instalasi rawat inap, Instalasi Pelayanan Intensif','M','5',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(3,'4e178d7e-6d29-11ec-a73f-1e544a7779f8',2,'Terjadinya lisis atau pembekuan darah yang tidak sesuai dengan syarat sampel darah yang baik','Semua darah yang lisis atau beku','Sampel pasien dengan kelainan darah yang menyebabkan lisisnya eritrosit, contoh : AIHA (Auto Imune Hemolitic Anemia ), PMN (Paroximal Nocturnal Hematuria), DIC, (DCSSDeminated Intravascular Coagulation), perdarahan dengan obat anti koagulan, misalnya heparin post dialisa','Kerusakan sampel darah','Catatan spesimen yang rusak','Input',NULL,'Instalasi laboratorium','M','0.5',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(4,'4e178fad-6d29-11ec-a73f-1e544a7779f8',2,'Keterlambatan melaporkan / tidak terlaporkannya hasil kritis, yaitu hasil laborat yang nilainya menurut patofisiologi penyakit berpotensi mengancam jiwa penderita sehingga membutuhkan penanganan medis secepat mungkin.','','','Tidak terlaporkannya hasil kritis','Catatan pelaporan hasil kritis','Input',NULL,'Instalasi Laboratorium dan Instalasi Rawat Inap','M','0',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(5,'4e179050-6d29-11ec-a73f-1e544a7779f8',2,'Kejadian&nbsp; yang menunjukkan banyaknya penolakan expertise oleh dokter pengirim','Semua perbedaan pandangan baik verbal maupun tertulis mengenai hasil radiologi antara dokter pengirim dengan dokter radiologi','','Penolakan expertise','Laporan insiden ','Outcome',NULL,'Instalasi rawat jalan, Instalasi rawat inap, ICU, IGD','M','1',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(6,'4e1790e7-6d29-11ec-a73f-1e544a7779f8',2,'Angka yang menunjukkan  keterlambatan penerimaan hasil foto oleh pasien rawat jalan lebih dari tiga jam.jalan lebih dari tiga jam.','Hasil  foto  diterima  lebih dari 3 jam  setelah   dilakukan  tindakan radiologi','Hasil pemeriksaan USG','Keterlambatan hasil foto rawat jalan','Catatan pelayanan radiologi','Outcome',NULL,'Instalasi rawat jalan, IGD','M','3',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(7,'4e17927f-6d29-11ec-a73f-1e544a7779f8',2,'Pemeriksaan ulang radiologiTerjadinya kesalahan pelaksanaan pemeriksaan radiologi','Pemeriksaan ulang radiologiTerjadinya kesalaPemeriksaan radiologi diulang karena salah posisi, kesalahan teknik fotografi,&nbsp; tidak sesuai dengan permintaan.han pelaksanaan pemeriksaan radiologi','Pemeriksaan ulang karena faktor pasien','Pemeriksaan ulang radiologi','Laporan insiden','Proses',NULL,'Instalasi radiologi','M','0.5',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(8,'4e179316-6d29-11ec-a73f-1e544a7779f8',2,'Asesmen awal radiologi adalah pemeriksaan pendahuluan yang dilakukan bagi semua pasien radiologi sebelum tindakan radiologi, serta didokumentasikan secara benar dan lengkap.','','','Tidak dilakukannya asesmen awal radiologi','Rekam medis (Form asesmen awal radiologi)','Input',NULL,'Instalasi radiologi','M','1',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(9,'4e1793a7-6d29-11ec-a73f-1e544a7779f8',2,'Tidak dilakukannya penandaan lokasi operasi oleh operator','Tidak dilakukannya penandaan lokasi operasi pada semua kasus operasi beda sisi / perbedaan kanan kiri (laterality), multiple struktur (jari tangan, jari kaki, lesi) atau multiple level (tulang belakang)','Operasi yang tidak memerlukan penandaan lokasi operasi antara lain :\n<ol>\n	<li>Terdapat luka atau lesi yang jelas dimana luka atau lesi tersebut menjadi bagian yang akan ditindak.</li>\n	<li>Kasus organ tunggal (contoh operasi caesar, jantung, TUR, sirkumsisi)</li>\n	<li>Kasus yang melibatkan gigi, mulut. (untuk penandaan gigi akan dilakukan di rontgent gigi)</li>\n	<li>Prosedur yang melibatkan bayi prematur di mana penandaan akan menyebabkan tato permanen.</li>\n</ol>\nSecara klinis atau anatomi tidak memungkinkan untuk diberi tanda : permukaan mukosa, perineum, amandel, hemoroid)','Tidak dilakukannya&nbsp; penandaan lokasi operasi','Status rekam medis pasien','Input',NULL,'Instalasi kamar operasi','M','2',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(10,'4e17953d-6d29-11ec-a73f-1e544a7779f8',2,'Dilakukannya operasi ulang (operasi dengan prosedur yang sama) dengan kasus / diagnosa yang sama dengan operasi sebelumnya dan / atau karena komplikasinya, dalam waktu 7 hari atau kurang.','','','Operasi ulang dengan diagnosa sama dan atau komplikasinya<br />\n&nbsp;','Status rekam medis pasien (laporan operasi)','Outcome',NULL,'Instalasi  rawat inap','M','0',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(11,'4e1795cc-6d29-11ec-a73f-1e544a7779f8',2,'Terjadi insiden kesalahan prosedur operasi pada saat pasien dilakukan tindakan operasi','Semua kesalahan prosedur operasi pada pasien yang mendapat tindakan pembedahan','','Kesalahan Prosedur Operasi','Laporan insiden','Proses-outcome',NULL,'Instalasi kamar operasi','M','0',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(12,'4e17965c-6d29-11ec-a73f-1e544a7779f8',2,'Terjadinya insiden kesalahan lokasi pada saat pasien dilakukan tindakan operasi','Semua kesalahan lokasi operasi pada pasien yang mendapat tindakan pembedahan','','Kesalahan Lokasi Operasi','Laporan insiden','Proses-outcome',NULL,'Instalasi Kamar  Operasi, Instalasi Rawat Inap','M','0',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(13,'4e1797de-6d29-11ec-a73f-1e544a7779f8',2,'Terjadinya insiden kesalahan diagnosis pada pasien pra operasi, yang baru diketahui oleh operator pada saat durante operasi (diagnosis pra dan post operasi berbeda)','Terjadinya kesalahan/ perbedaan antara&nbsp; diagnosis pra dengan post operasi yang disebabkan oleh apapun','','Kesalahan Diagnosa Pre dan post operasi','Laporan insiden','Proses-outcome',NULL,'Instalasi Kamar  Operasi, Instalasi Rawat Inap','M','0',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(14,'4e17986c-6d29-11ec-a73f-1e544a7779f8',2,'Kesalahan&nbsp; penyerahan&nbsp;&nbsp; perbekalan&nbsp;&nbsp; farmasi (obat, alat kesehatan, dan sebagainya) dari Instalasi Farmasi ke ruang perawatan','Kesalahan penyerahan perbekalan farmasi yang berupa :\n<ul>\n	<li>Jenis obat</li>\n	<li>Dosis</li>\n	<li>Tujuan/tempat</li>\n	<li>Jumlah</li>\n</ul>\n','','Kesalahan penyerahan perbekalan farmasi','Pelaporan insiden','Proses',NULL,'Instalasi Farmasi, Instalasi rawat inap, Instalasi rawat jalan, ICU, IGD, HD, Endoskopi','M','0',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(15,'4e1799f7-6d29-11ec-a73f-1e544a7779f8',2,'Ketidaktepatan pemberian obat kepada pasien yang dinilai berdasarkan 5 benar, yaitu\n<ol>\n	<li>Benar pasien</li>\n	<li>Benar obat</li>\n	<li>Benar dosis</li>\n	<li>Benar waktu pemberian</li>\n	<li>Benar cara pemberian</li>\n</ol>\n','Kesalahan / ketidaktepatan pemberian obat&nbsp; (5 Benar)','','Ketidaktepatan pemberian obat (5 benar)','Laporan insiden','Proses',NULL,'Instalasi Farmasi, instalasi rawat inap, Instalasi rawat jalan, IGD, ICU, HD, Endoskopi','M','0',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(16,'4e179a87-6d29-11ec-a73f-1e544a7779f8',2,'Ketidaklengkapan asesmen pre anestesi&nbsp; meliputi : dokter anestesi&nbsp; tidak visite pada saat pasien masih di ruang perawatan (pemeriksaan fisik, pemeriksaan penunjang, KIE / Informed Consent), dan rekam medis tidak terisi secara lengkap sebelum pasien dilakukan anestesi.','Semua pasien yang akan dilakukan operasi dengan pembiusan','<ul>\n	<li>Pasien operasi dengan anestesi lokal</li>\n	<li>Pasien anestesi bukan untuk tindakan operasi melainkan untuk pemeriksaan diagnostic</li>\n</ul>\n','Ketidaklengkapan asesmen pre anestesi','Status rekam medis pasien','Input',NULL,'Instalasi kamar operasi','M','1',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(17,'4e179c10-6d29-11ec-a73f-1e544a7779f8',2,'Yang dimaksud kejadian reaksi transfusi adalah reaksi yang timbul akibat dilakukannya transfusi darah yang tidak sesuai dengan golongan darah pasien. (Reaksi incompatibilitas)','Transfusi darah yang diberikan tidak cocok dengan golongan darah pasien.','Kelainan pada darah atau sepsis yang bukan disebabkan oleh transfusi darah.','Kejadian Reaksi Transfusi','Status rekam medis pasien, laporan insiden','Proses',NULL,'Instalasi rawat inap','M','0',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(18,'4e179cf5-6d29-11ec-a73f-1e544a7779f8',2,'Informed Concent adalah persetujuan tindakan kedokteran yang diberikan oleh pasien/keluarga terdekatnya setelah mendapatkan penjelasan secara lengkap mengenai tindakan kedokteran yang akan dilakukan terhadap pasien tersebut serta risiko yang akan terjadi terhadap pasien.<br />\nKetidaklengkapan informed consent adalah tidak terisinya form informed consent secara lengkap, data maupun tanda tangan, baik pada lembar informasi maupun pada lembar consent.<br />\n&nbsp;','','','Ketidaklengkapan informed consent','Rekam medis pasien','Input dan outcome',NULL,'Instalasi rekam medis','M','1',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(19,'4e179e81-6d29-11ec-a73f-1e544a7779f8',2,'Ketidaklengkapan pengisian catatan medis yang berisi seluruh informasi tentang pasien sesuai dengan formulir yang disediakan, khususnya resume medis dan resume keperawatan termasuk seluruh hasil pemeriksaan penunjang, dalam waktu 14 hari setelah pasien keluar dari Rumah Sakit','Identitas pasien, data perjalanan penyakit (anamnesa, pemeriksaan fisik, pemeriksaan penunjang, diagnosis, terapi, tindakan yang dilengkapi dengan informed consent, laporan), tanda tangan dokter','','Ketidaklengkapan catatan medis pasien (KLPCM)','Rekam medis pasien','Outcome',NULL,'Instalasi rekam medis','M','1',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(20,'4e179f15-6d29-11ec-a73f-1e544a7779f8',2,'Infeksi pasca operasi adalah adanya infeksi rumah sakit (HAIs) pada semua kategori luka sayatan operasi yang dilaksanakan di rumah sakit dan ditandai oleh rasa panas (kalor), nyeri (dolor), kemerahan (rubor), bengkak (tumor) gangguan fungsi (fungsiolesa) dan keluarnya nanah (pus) yang muncul dalam waktu lebih 3 x 24 jam sampai dengan 30 hari pasca operasi, atau sampai dengan 1 tahun jika terdapat implant','Semua infeksi pada daerah operasi yang terjadi minimal 3 x 24 jam pasca operasi sampai dengan 30 hari atau satu tahun jika dipasang implant.','Jejunostomy, ileostomy, colostomy','Infeksi Daerah&nbsp; Operasi (IDO)','Rekam medis pasien','Proses dan outcome',NULL,'Intalasi rawat inap, ICU, Instalasi Rawat Jalan','M','2',2,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(21,'4e17a09d-6d29-11ec-a73f-1e544a7779f8',2,'Sepsis yang terjadi setelah pasien dirawat di rumah sakit','Gejala&nbsp; yang&nbsp; timbul&nbsp; :&nbsp; panas, hiperventilasi, alkalosis&nbsp; respiratoris, perubahan status mental, hipotensi, shock (Sepsis ditentukan oleh dokter yang merawat)','Pasien masuk rumah sakit dengan sepsis','Sepsis','Rekam medis pasien','Proses dan outcome',NULL,'Intalasi rawat inap, ICU','M','1',2,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(22,'4e17a135-6d29-11ec-a73f-1e544a7779f8',2,'Keadaan infeksi yang terjadi disekitar tusukan atau bekas tusukan jarum infus di pembuluh darah perifer dan timbul minimal 48 jam setelah pemasangan (sesuai pedoman surveilans infeksi Kemenkes RI tahun 2011).','Pada daerah&nbsp; bekas tusukan dan daerah sekitarnya terdapat peradangan yang ditandai dengan salah satu dari gejala ini : rasa panas, pengerasan/ bengkak, kemerahan, dan terasa sakit bila ditekan (kalor, dolor, tumor, rubor dan functiolaesa) dengan atau tanpa nanah (pus) tanpa dilengkapi pemeriksaan kultur.','<ul>\n	<li>Infeksi kulit karena sebab-sebab lain</li>\n	<li>Adanya bakteremia dengan pemeriksaan kultur</li>\n	<li>Usia &le; 1 tahun</li>\n</ul>\n','Plebitis','Rekam medis pasien','Proses dan outcome',NULL,'Intalasi rawat inap, ICU','M','20',2,1,'1000',NULL,'&permil;',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(23,'4e17a2fa-6d29-11ec-a73f-1e544a7779f8',2,'Keadaan infeksi yang terjadi akibat masuknya mikroba melalui peralatan yang dimasukkan langsung ke sistem pembuluh darah melalui insersi intravena kateter, baik berupa kateter vena maupun arteri dalam rangka perawatan maupun diagnostik (CVC / Central Venous Catheter, vena perifer / infus, double lumen untuk hemodialisa) infeksi timbul minimal 3 kali 24 jam&nbsp; (72 jam) setelah pemasangan.','<ul>\n	<li>Pasien menunjukkan minimal satu dari gejala klinik :&nbsp;&nbsp; (suhu &gt; 380C), menggigil, hipotensi, untuk usia &le; 1 tahun ditambah dengan hipotermi (suhu &lt; 370C), apnoe dan bradikardi.</li>\n	<li>Hasil positif dari pemeriksaan kultur darah dan tidak berhubungan dengan infeksi di bagian lain dari tubuh pasien.</li>\n	<li>Ditemukan kuman pathogen pada kultur darah pasien positif</li>\n	<li>Hasil kultur darah didapatkan&nbsp; mikroba kontaminan kulit yang umum (corynebacterium, bacilus, propionibacterium, satphylococcus epidermidis, streptococcus viridans, aerococcus, micrococcus)</li>\n</ul>\n','<ul>\n	<li>Infeksi kulit karena sebab-sebab lain</li>\n	<li>Tidak disertai dengan hasil kultur darah</li>\n</ul>\n','Infeksi Aliran Darah Primer&nbsp; (IADP)','Rekam medis pasien','Proses dan outcome',NULL,'Intalasi rawat inap, ICU','M','10',2,1,'1000',NULL,'&permil;',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(24,'4e17a48e-6d29-11ec-a73f-1e544a7779f8',2,'Keadaan&nbsp; infeksi&nbsp; yang&nbsp; terjadi&nbsp; disekitar&nbsp; uretra atau selang kateter dan timbul setelah 3 kali 24 jam dilakukan pemasangan kateter di rumah sakit.','Pada daerah uretra terjadi iritasi, gatal-gatal, rasa sakit atau panas, pus, dan urine berwarna merah atau keruh','Jika keadaan tersebut timbul oleh suatu tindakan lain atau oleh karena penyakitnya.','Infeksi Saluran Kemih (ISK)','Rekam medis pasien','Proses dan outcome',NULL,'Intalasi rawat inap, Instalasi Pelayanan Intensif','M','10',2,1,'1000',NULL,'&permil;',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(25,'4e17a61d-6d29-11ec-a73f-1e544a7779f8',2,'Ventilator Associated Pneumonia (VAP) adalah pneumonia yang terjadi akibat pemasangan ventilator di rumah sakit.','Gejala pneumonia muncul minimal 2 x 24 jam setelah pemasangan Endotracheal Tube (ETT)','<ul>\n	<li>Pasien&nbsp; yang&nbsp; telah&nbsp; terpasang&nbsp; Endo Trakeal Tube sebelum pasien masuk rumah sakit</li>\n	<li>Gejala pneumonia muncul kurang dari 2 x 24 jam&nbsp; setelah pemasangan Endotracheal Tube (ETT)</li>\n</ul>\n','Pneumonia akibat pemakaian ventilator (Ventilator Associated Pneumonia /VAP)','Rekam medis pasien','Proses dan outcome',NULL,'Instalasi Pelayanan Intensif','M','20',1,1,'1000',NULL,'&permil;',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(26,'4e17a7ca-6d29-11ec-a73f-1e544a7779f8',2,'Kerusakan/kematian kulit sampai jaringan dibawah kulit, bahkan menembus otot sampai mengenai tulang akibat adanya penekanan pada suatu area secaraterus menerus sehingga mengakibatkan gangguan sirkulasi darah setempat, yang timbul minimal 3 x 24 jam setelah rawat inap','Luka lecet pada bagian-bagian tubuh pasien yang terkena tekanan karena tirah baring','<ul>\n	<li>Luka lecet yang terjadi diluar area pada pasien tirah baring</li>\n	<li>Pasien yang sudah mengalami dekubitus sebelum rawat inap</li>\n</ul>\n','Kejadian dekubitus selama masa perawatan<br />\n&nbsp;','Rekam medis pasien','Proses dan outcome',NULL,'Instalasi Rawat Inap dan Instalasi Pelayanan Intensif, Unit stroke','M','0',2,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(27,'4e17a963-6d29-11ec-a73f-1e544a7779f8',2,'Ketidaktepatan identifikasi adalah kesalahan penentuan identitas pasien sejak awal pasien masuk sampai dengan pasien keluar,terhadap semua pelayanan yang diterima oleh pasien','<ul>\n	<li>Ketidaktepatan penulisan identitas (nama, tanggal lahir,&nbsp; nomor RM)</li>\n	<li>Ketidaktepatan pemilihan gelang identitas</li>\n	<li>Ketidaktepatan prosedur konfirmasi identitas pasien (antara lain konfirmasi dengan pertanyaan terbuka)</li>\n</ul>\n','','Ketidaktepatan identifikasi pasien','Laporan insiden','Proses-outcome',NULL,'Semua unit ','M','0',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(28,'4e17ab02-6d29-11ec-a73f-1e544a7779f8',2,'Obat yang perlu diwaspadai (High allert ) adalah obat yang memiliki risiko lebih tinggi untuk menyebabkan&nbsp; / menimbulkan adanya komplikasi atau membahayakan pasien secara signifikan jika terdapat kesalahan penggunaan dan penyimpanan.','<ul>\n	<li>Penyimpanan obat high allert&nbsp; tidak dilakukan secara benar (prosedur penyimpanan yang benar : obat High Allert disimpan terpisah; elektrolit konsentrat diberi stiker orange; NORUM / LASA diberi stiker hijau ; insulin dan nutrisi parenteral diberi stiker kuning; obat sedasi, heparin, agen radiokntras IV diberi stiker merah; agen kemoterapi diberi stiker ungu)</li>\n	<li>Pemberian obat High Allert tidak menggunakan prosedur 5 (lima) Benar</li>\n	<li>Tidak ada daftar obat High allert di masing-masing unit</li>\n	<li>Prosedur ejaan tidak digunakan untuk obat yang bersifat LASA / NORUM</li>\n</ul>\n','Obat-obatan yang tidak tergolong High Allert','Insiden keamanan obat yang perlu diwaspadai','Laporan insiden','Proses-outcome',NULL,'Semua unit pelayanan','M','0',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(29,'4e17abab-6d29-11ec-a73f-1e544a7779f8',2,'Pasien jatuh di lingkungan rumah sakit oleh sebab apapun','Semua insiden pasien jatuh di lingkungan rumah sakit','','Kejadian pasien jatuh','Laporan insiden','Proses-outcome',NULL,'Seluruh area Rumah sakit ','M','0',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(30,'4e17ac44-6d29-11ec-a73f-1e544a7779f8',2,'<ul>\n	<li>Pemberian obat anti trombotik kepada pasien stroke ischemic</li>\n	<li>Preparat anti trombotik yang berisi: asam asetil salisilat, clopidogrel</li>\n	<li>Diisi oleh unit yang memulangkan pasien</li>\n</ul>\n','Semua pasien stroke ischemic yang KRS','Pasien stroke non ischemic','Pasien stroke ischemic yang tidak mendapatkan terapi anti trombotik pada saat KRS.','Rekam medis','Proses dan outcome',NULL,'Unit Stroke, Instalasi Rawat Inap dan Instalasi Pelayanan Intensif','M','0',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(31,'4e17ae23-6d29-11ec-a73f-1e544a7779f8',2,'<ul>\n	<li>Edukasi pasien stroke adalah pemberian informasi dan pendidikan seputar stroke terhadap pasien dan / atau keluarga yang dilakukan oleh dokter penanggung jawab / perawat / fisioterapis / ahli gizi / apoteker atau tenaga kesehatan lainnya.</li>\n	<li>Diisi oleh unit yang pertama kali menerima&nbsp; pasien</li>\n</ul>\n','Semua pasien stroke yang dirawat di Rumah sakit','','Pasien stroke yang tidak mendapatkan edukasi selama masa perawatan di rumah sakit','Rekam medis','Proses dan outcome',NULL,'Unit Stroke, Instalasi Rawat Inap dan Instalasi Pelayanan Intensif','M','0',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(32,'4e17aebe-6d29-11ec-a73f-1e544a7779f8',2,'<ul>\n	<li>Pemberian terapi aspirin kepada pasien Infark Miokard Akut dalam waktu 24 jam sebelum atau sesudah tiba di rumah sakit .</li>\n	<li>Preparat anti trombotik yang berisi: asetil salisilat, clopidogrel</li>\n</ul>\n','Semua pasien Infark Miokard Akut (IMA)','','Pasien IMA yang tidak mendapatkan terapi aspirin (anti trombotik) dalam waktu 24 jam sejak datang ke Rumah Sakit.','Rekam medis','Proses dan outcome',NULL,'Instalasi Rawat Inap dan Instalasi Pelayanan Intensif','M','0',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(33,'4e17af49-6d29-11ec-a73f-1e544a7779f8',2,'Pemberian Air Susu Ibu saja kepada bayi umur 0 &ndash; 6 bulan tanpa diberikan makanan atau minuman tambahan selain obat untuk terapi (pengobatan penyakit) selama masa rawat inap','Semua bayi baru lahir selama masa rawat inap di rumah sakit','Bayi yang menderita galaktosemia , maple syrup urine, dan fenilketonuria','Bayi baru lahir yang tidak mendapatkan ASI Eksklusif selama rawat inap','Rekam medis','Proses dan outcome',NULL,'Unit perinatologi','M','0',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(34,'4e17b0ef-6d29-11ec-a73f-1e544a7779f8',2,'Pemberian obat brokodilator pada pasien asma anak (&lt; 15 tahun) selama masa rawat inap','Semua pasien asma pada anak','','Pasien asma anak yang tidak menerima bronkodilator selama masa rawat inap','Rekam medis','Proses dan outcome',NULL,'Instalasi Rawat Inap dan Instalasi Pelayanan Intensif','M','0',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(35,'4e17b181-6d29-11ec-a73f-1e544a7779f8',2,'Pelayanan tuberkulosis dengan strategi DOTS adalah pelayanan tuberkulosis dengan 5 (lima) strategi penanggulangan tuberkulosis nasional.<br />\nPenegakan diagnosis dan follow up pengobatan pasien tuberkulosis harus melalui pemeriksaan mikroskopis tuberkulosis, pengobatan harus menggunakan paduan obat anti tuberkulosis yang sesuai dengan standar penanggulangan tuberkulosis nasional, dan semua pasien yang tuberkulosis yang diobati dievaluasi secara kohort sesuai dengan penanggulangan tuberkulosis nasional','Pasien tuberkulosis paru maupun ekstra paru','','Penanganan pasien tuberkulosis yang tidak sesuai strategi DOTS (Directly Observed Treatment Shortcourse)','Rekam Medis','Proses',NULL,'Poli DOTS','M','0',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(36,'4e17b285-6d29-11ec-a73f-1e544a7779f8',2,'Terduga TB : adalah semua pasien yang&nbsp; diduga menderita tuberkulosis<br />\nTerkonfirmasi bakteriologis : minimal 1 (satu) dari 3 (tiga) spesimen pemeriksaan dahak adalah BTA(+','','','Proporsi pasien TB paru terkonfirmasi bakteriologis diantara terduga TB','TB 04, TB 06','Input, proses',NULL,'Laboratorium, Poli DOTS','M','5-15',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(37,'4e17b448-6d29-11ec-a73f-1e544a7779f8',2,'Angka konversi adalah prosentase pasien TB paru terkonfirmasi bakteriologis yang mengawali perubahan menjadi BTA negatif setelah menjalani masa pengobatan tahap awal&nbsp; diantara pasien TB paru terkonfirmasi bakteriologis yang diobati.','','','Angka konversi','TB 03, TB 04','Proses, outcome',NULL,'Poli DOTS','M','80',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(38,'4e17b4d4-6d29-11ec-a73f-1e544a7779f8',2,'Angka kesembuhan adalah angka yang menunjukkan prosentase pasien TB paru terkonfirmasi bakteriologis yang sembuh setelah selesai masa pengobatan diantara pasien TB paru terkonfirmasi bakteriologis&nbsp; yang tercatat.','','','Angka kesembuhan','TB 01 dan TB 03','Proses, outcome',NULL,'Poli DOTS','M','85',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(39,'4e17b55b-6d29-11ec-a73f-1e544a7779f8',2,'Insiden yang menunjukkan banyaknya ibu yang meninggal karena eklampsia<br />\nEklampsia adalah suatu kelainan akut yang terjadi pada wanita hamil, bersalin, atau nifas yang ditandai dengan pre-eklampsia serta timbulnya kejang-kejang atau komplikasi lainnya, yang bukan disebabkan karena kelainan neurologi','Semua ibu hamil / bersalin / nifas yang mengalami eklampsia.','Hipertensi menahun (kronik)','Kematian ibu melahirkan karena eklampsi','Rekam medis pasien','Outcome',NULL,'Unit Kamar bersalin','M','0.5',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(40,'4e17b704-6d29-11ec-a73f-1e544a7779f8',2,'Insiden yang menunjukkan banyaknya ibu yang meninggal karena perdarahan yang dapat terjadi pada semua kala dalam persalinan','Disebabkan antara lain APB, ruptur uteri,&nbsp; kegagalan uri (placenta) untuk keluar secara spontan (retentio placenta), tidak berkontraksinya rahim ibu (atonia uteri)','Perdarahan&nbsp; karena&nbsp; trauma&nbsp; pada&nbsp;&nbsp; perut&nbsp; atau karena tindakan fisik yang lain yang tidak berhubungan dengan proses persalinan','Kematian ibu melahirkan karena perdarahan','Rekam medis pasien','Outcome',NULL,'Unit Kamar bersalin','M','0.5',1,1,'100',NULL,'%',NULL,NULL,NULL,'2021-12-31','2020-11-30 00:00:00',NULL,'A',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(41,'4e17b79c-6d29-11ec-a73f-1e544a7779f8',2,'BBLR adalah 