DROP TABLE IF EXISTS `sidokaf_accreditation_transaction`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sidokaf_accreditation_transaction` (
  `transaction_id` int(11) NOT NULL AUTO_INCREMENT,
  `transaction_accreditation_id` int(11) DEFAULT NULL,
  `transaction_event_id` int(11) NOT NULL,
  `transaction_instrument_id` int(11) NOT NULL,
  `transaction_chapter_id` int(11) DEFAULT NULL,
  `transaction_instrument_reference_code` varchar(50) DEFAULT NULL,
  `transaction_standard_id` int(11) DEFAULT NULL,
  `transaction_institution_code` varchar(11) NOT NULL,
  `transaction_institution_score` varchar(3) DEFAULT NULL,
  `transaction_institution_update_date` datetime DEFAULT NULL,
  `transaction_institution_update_by` int(11) DEFAULT NULL,
  `transaction_institution_is_approved` int(11) DEFAULT NULL,
  `transaction_institution_approve_date` datetime DEFAULT NULL,
  `transaction_surveyor_update_by` char(5) DEFAULT NULL,
  `transaction_surveyor_score` varchar(3) DEFAULT '0',
  `transaction_surveyor_fact_and_analysis` text DEFAULT NULL,
  `transaction_surveyor_recommendation` text DEFAULT NULL,
  `transaction_surveyor_need_to_discussed` int(11) DEFAULT NULL,
  `transaction_surveyor_update_date` datetime DEFAULT NULL,
  `transaction_counselor_update_by` char(5) DEFAULT NULL,
  `transaction_counselor_score` varchar(3) DEFAULT '0',
  `transaction_counselor_fact_and_analysis` text DEFAULT NULL,
  `transaction_counselor_note` text DEFAULT NULL,
  `transaction_counselor_message` text DEFAULT NULL,
  `transaction_evaluation_x1` char(1) DEFAULT NULL,
  `transaction_evaluation_x2` char(1) DEFAULT NULL,
  `transaction_evaluation_x3` char(1) DEFAULT NULL,
  `transaction_counselor_update_date` datetime DEFAULT NULL,
  `transaction_counselor_is_approved` int(11) DEFAULT NULL,
  `transaction_counselor_approved_date` date DEFAULT NULL,
  `transaction_remedial_surveyor_update_by` char(5) DEFAULT NULL,
  `transaction_remedial_surveyor_score` varchar(3) DEFAULT NULL,
  `transaction_remedial_surveyor_fact_and_analysis` text DEFAULT NULL,
  `transaction_remedial_surveyor_recommendation` text DEFAULT NULL,
  `transaction_remedial_surveyor_update_date` datetime DEFAULT NULL,
  `transaction_final_score` varchar(3) DEFAULT '0',
  `transaction_is_evaluated` int(11) DEFAULT NULL,
  `transaction_is_discussed` int(11) DEFAULT NULL,
  `transaction_verification_1` varchar(10) DEFAULT NULL,
  `transaction_verification_1_recommendation` text DEFAULT NULL,
  `transaction_verification_1_insert_by` varchar(6) DEFAULT NULL,
  `transaction_verification_1_insert_date` datetime DEFAULT NULL,
  `transaction_verification_2` varchar(10) DEFAULT NULL,
  `transaction_verification_2_recommendation` text DEFAULT NULL,
  `transaction_verification_2_insert_by` varchar(6) DEFAULT NULL,
  `transaction_verification_2_insert_date` datetime DEFAULT NULL,
  `transaction_document_amount` int(11) NOT NULL DEFAULT 0,
  `transaction_record_status` char(1) NOT NULL,
  `transaction_period` year(4) NOT NULL,
  PRIMARY KEY (`transaction_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3649 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci ROW_FORMAT=DYNAMIC;
