  `trans_final_score_0` int(11) DEFAULT NULL,
  `trans_final_score_5` int(11) DEFAULT NULL,
  `trans_final_score_10` int(11) DEFAULT NULL,
  `trans_final_is_tdd` char(1) NOT NULL DEFAULT '0',
