--
-- Table structure for table `user_profile`
--

DROP TABLE IF EXISTS `user_profile`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `user_profile` (
  `profile_id` int(11) NOT NULL AUTO_INCREMENT,
  `profile_group_id` char(20) NOT NULL,
  `profile_subgroup_id` varchar(50) NOT NULL,
  `profile_operator_id` int(11) DEFAULT NULL,
  `profile_fullname` varchar(100) NOT NULL,
  `profile_employee_id` varchar(25) DEFAULT NULL,
  `profile_birth_place` varchar(50) DEFAULT NULL,
  `profile_dob` date DEFAULT NULL,
  `profile_gender` int(11) DEFAULT NULL,
  `profile_religion` int(11) DEFAULT NULL,
  `profile_address` varchar(300) DEFAULT NULL,
  `profile_city_code` char(5) DEFAULT NULL,
  `profile_city_name` varchar(30) DEFAULT NULL,
  `profile_district_code` char(7) DEFAULT NULL,
  `profile_village_code` char(10) DEFAULT NULL,
  `profile_postcode` varchar(5) DEFAULT NULL,
  `profile_living_address` varchar(300) DEFAULT NULL,
  `profile_living_city_code` char(5) DEFAULT NULL,
  `profile_living_province_code` char(2) DEFAULT NULL,
  `profile_living_district_code` char(7) DEFAULT NULL,
  `profile_living_village_code` char(10) DEFAULT NULL,
  `profile_living_postcode` varchar(5) DEFAULT NULL,
  `profile_province_code` char(2) DEFAULT NULL,
  `profile_province_name` varchar(30) DEFAULT NULL,
  `profile_handphone1` char(20) DEFAULT NULL,
  `profile_handphone2` char(20) DEFAULT NULL,
  `profile_email` varchar(100) DEFAULT NULL,
  `profile_gmail` varchar(100) DEFAULT NULL,
  `profile_npwp` varchar(25) DEFAULT NULL,
  `profile_fullname_npwp` varchar(50) DEFAULT NULL,
  `profile_bank` varchar(50) DEFAULT NULL,
  `profile_bank_account` varchar(25) DEFAULT NULL,
  `profile_bank_account_holder` varchar(50) DEFAULT NULL,
  `profile_competency_id` varchar(8) DEFAULT NULL,
  `profile_nationality_id` varchar(20) DEFAULT NULL,
  `profile_str_id` varchar(50) DEFAULT NULL,
  `profile_str_expired` date DEFAULT NULL,
  `profile_sip_id` varchar(50) DEFAULT NULL,
  `profile_sip_expired` date DEFAULT NULL,
  `profile_spk_id` varchar(50) DEFAULT NULL,
  `profile_spk_expired` date DEFAULT NULL,
  `profile_rkk_id` varchar(50) DEFAULT NULL,
  `profile_rkk_expired` date DEFAULT NULL,
  `profile_work_type` char(1) DEFAULT NULL,
  `profile_work_status` int(11) DEFAULT NULL,
  `profile_work_position` int(11) DEFAULT NULL,
  `profile_work_date` date DEFAULT NULL,
  `profile_workshop_partnership_id` int(11) DEFAULT NULL,
  `profile_department_id` varchar(10) DEFAULT NULL,
  `profile_signs` char(36) DEFAULT NULL,
  `profile_specialize_id` char(1) DEFAULT NULL,
  `profile_major` char(1) DEFAULT NULL COMMENT '1:Dokter;2:Dokter Gigi;3:SKM;4:Bidan;5:Perawat dan nakes lainnya',
  `profile_insert_by` varchar(5) NOT NULL,
  `profile_insert_date` datetime NOT NULL,
  `profile_is_verified` tinyint(1) DEFAULT 0,
  `profile_verification_token` varchar(255) DEFAULT NULL,
  `profile_verification_sent_at` datetime DEFAULT NULL,
  `profile_verified_at` datetime DEFAULT NULL,
  `profile_update_by` varchar(5) DEFAULT NULL,
  `profile_update_date` datetime DEFAULT NULL,
  `profile_delete_date` datetime DEFAULT NULL,
  `profile_delete_by` int(11) DEFAULT NULL,
  `profile_institution_code` varchar(11) DEFAULT NULL,
  `profile_institution_name` varchar(200) DEFAULT NULL,
  `profile_institution_ownership_id` char(2) DEFAULT NULL,
  `profile_institution_province_code` varchar(50) DEFAULT NULL COMMENT 'Province tempat kerja',
  `profile_institution_city_code` varchar(10) DEFAULT NULL COMMENT 'Kab//Kota tempat kerja',
  `profile_institution_group_id` varchar(10) DEFAULT NULL COMMENT '5 = Puskesmas; 12 = Klinik; 13=Praktek Dokter Mandiri',
  `profile_regional_city_code` varchar(6) DEFAULT NULL,
  `profile_batch` char(4) DEFAULT NULL,
  `profile_bpjs_number` varchar(25) DEFAULT NULL,
  `profile_toefl_score` varchar(5) DEFAULT NULL,
  `profile_photo` varchar(250) DEFAULT NULL,
  `profile_grade_code` varchar(2) DEFAULT NULL,
  `profile_password` varchar(32) DEFAULT NULL,
  `profile_last_change_password` datetime DEFAULT NULL,
  `profile_online_status` int(11) NOT NULL DEFAULT 0,
  `profile_remember_token` varchar(64) DEFAULT NULL,
  `profile_disable` int(11) NOT NULL DEFAULT 0 COMMENT '0 = Active; 1=Disable',
  `profile_disable_reason` int(11) DEFAULT NULL,
  `profile_note` varchar(250) DEFAULT NULL,
  `profile_last_login` datetime DEFAULT NULL,
  `profile_partnership_code` varchar(32) DEFAULT NULL COMMENT 'Status Penanggunjawab yang bisa dihubungu',
  `profile_partnership_ed` date DEFAULT NULL,
  `profile_record_status` char(1) NOT NULL DEFAULT 'A',
  `mod_id` text NOT NULL,
  `mod_id_grop` varchar(255) NOT NULL,
  PRIMARY KEY (`profile_id`)
) ENGINE=InnoDB AUTO_INCREMENT=133 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci ROW_FORMAT=COMPACT;
/*!40101 SET character_set_client = @saved_cs_client */;

